    lecture_flatsolid_title: "Урок: Плоские и объёмные фигуры",
    lecture_flatsolid_sub: "Научись отличать плоские фигуры от объёмных",
    flatsolid_s1_title: "Плоские и объёмные фигуры",
    flatsolid_s1_text: "Барыс показывает разные предметы! Сегодня научимся отличать плоские фигуры от объёмных. Готов разобраться?",
    flatsolid_s2_title: "Плоские фигуры",
    flatsolid_s2_text: "Плоские фигуры — как рисунок на бумаге, у них нет толщины. Например, круг или квадрат — их можно нарисовать одним листом.",
    flatsolid_s3_title: "Объёмные фигуры",
    flatsolid_s3_text: "Объёмные фигуры — это предметы, которые можно покрутить в руках, у них есть толщина и объём. Например, мяч (шар) или кубик (куб).",
    flatsolid_s4_title: "Мяч и круг — не одно и то же",
    flatsolid_s4_text: "Круг — плоский, его можно нарисовать. А мяч — объёмный, круглый со всех сторон, его можно катать.",
    flatsolid_s5_title: "Проверь предмет",
    flatsolid_s5_text: "Посмотри на предмет: если его можно взять в руки и покрутить — он объёмный. Если он как картинка на бумаге — он плоский. Например, банка — объёмная, а квадрат на листе — плоский.",
    flatsolid_s6_title: "Ты умеешь отличать фигуры!",
    flatsolid_s6_text: "Барыс гордится тобой — теперь ты умеешь отличать плоские фигуры от объёмных! Готов проверить себя в игре?",
    flatsolid_game_title: "Плоская или пространственная?",
    flatsolid_game_sub: "Этот предмет плоский, как лист бумаги, или объёмный, как мяч?",
    flatsolid_explain: "Барыс показывает разные предметы! Плоские фигуры — как рисунок на бумаге, у них нет толщины, например круг или квадрат. А пространственные фигуры — объёмные, их можно покрутить в руках, например мяч (шар) или кубик (куб). Посмотри на предмет и подумай: он плоский или пространственный? Готов разобраться?",
    btn_flat: "Плоская",
    btn_solid: "Пространственная",
