    hub_measure_desc: "Длина, масса или объём?",
    measure_explain: "Барыс учится выбирать правильную меру! Карандаш измеряют длиной, яблоко — массой, а воду в бутылке — объёмом. Посмотри на предмет и выбери, чем его измеряют. Готов?",
