    hub_coins_desc: "Сколько тенге?",
    coins_explain: "Барыс учится узнавать монеты Казахстана! В Казахстане есть монеты в 1, 2, 5, 10 и 20 тенге. Посмотри на монету и определи, сколько на ней написано. Готов посчитать деньги?",
