    alippe_letters1_game_sub: "Бұл сурет қай әріптен басталады?",
    hub_alippe_letters2_title: "Әріпті тап (2-топ)",
    hub_alippe_letters2_desc: "с, о, т, қ, ы, м, е, д, ш, ұ",
    alippe_letters2_explain: "Барыс әліппені әрі қарай үйренеді! Бірінші топтан кейін мына дыбыстар келеді: с, о, т, қ, ы, м, е, д, ш, ұ. Суретке қара да, оның атауы қай әріптен басталатынын тап. Жалғастыруға дайынсың ба?",
    hub_prebukvar_title: "Дыбыс, буын, сөз, сөйлем",
    hub_prebukvar_desc: "Тілдің құпияларын ашайық",
    alippe_letters1_explain: "Барыс қазақ тілінің әліппесін үйренеді! Ахмет Байтұрсынұлы әдісі бойынша, алдымен ең жиі кездесетін дыбыстар үйретіледі: а, р, л, н. Суретке қара да, оның атауы қай әріптен басталатынын тап. Әліппені үйренуге дайынсың ба?",
