    hub_vowelharmony_desc: "Дауысты дыбыстар",
    vowelharmony_explain: "Барыс дауысты дыбыстардың жуан және жіңішке болатынын үйренеді! Жуан дауыстылар: а, о, ұ, ы. Жіңішке дауыстылар: ә, е, ө, ү, і. Әріпке қара да, ол жуан ба, жіңішке ме, анықта. Дайынсың ба?",
