    hub_capital_title: "Бас әріппен бе?",
    hub_capital_desc: "Есімдер мен жалпы сөздер",
    capital_explain: "Барыс учится, какие слова пишутся с заглавной буквы! Имена людей (Айгүл), названия городов (Алматы) и клички животных (Ақбар) — с заглавной. Обычные слова (қала — город, ит — собака) — с маленькой. Прочитай слово и выбери верный вариант. Готов?",
