    hub_wordharmony_title: "Сөз жуан ба, жіңішке ме?",
    hub_wordharmony_desc: "Дауысты дыбыстардың заңы",
    wordharmony_explain: "Барыс сингармонизм заңын үйренеді! Қазақ сөзінде барлық дауыстылар не бәрі жуан, не бәрі жіңішке болады. Сөзге қара да, ол жуан сөз бе, жіңішке сөз бе, анықта. Дайынсың ба?",
    wordharmony_game_title: "Сөз жуан ба, жіңішке ме?",
    wordharmony_game_sub: "Бұл сөз жуан ба, жіңішке ме?",
    anatili_q4_note: "Остальные темы этой четверти требуют настоящей устной речи и письма от руки — не геймифицируются кнопками",
