    hub_lecture_kazakh_title: "Видео-урок: Сәлем!",
    hub_lecture_kazakh_desc: "Первые казахские слова и фразы",
    lecture_kazakh_video_title: "Видео-урок: Сәлем!",
    lecture_kazakh_explain: "Барыс приглашает тебя на видео-урок по казахскому языку! Учитель покажет, как поздороваться и спросить имя по-казахски — «Сәлем! Сенің атың кім?». Ты уже играл в наши игры про казахские слова, а теперь услышишь живую казахскую речь. Готов посмотреть?",
    hub_lecture_estestvo_title: "Видео-урок: части растения",
    hub_lecture_estestvo_desc: "Растения подробнее",
    lecture_estestvo_video_title: "Видео-урок: части растения!",
    lecture_estestvo_explain: "Барыс приглашает тебя на видео-урок по естествознанию! Ты уже играл в нашу игру про части растения — а теперь посмотри настоящий видео-урок, где учитель подробно расскажет про корень, стебель, лист, цветок и плод. Готов посмотреть?",
    hub_lecture_digital_title: "Видео-урок: устройства",
    hub_lecture_digital_desc: "Компьютер подробнее",
    lecture_digital_video_title: "Видео-урок: устройства!",
    lecture_digital_explain: "Барыс приглашает тебя на видео-урок по цифровой грамотности! Ты уже играл в нашу игру про устройства компьютера — а теперь посмотри мультфильм, где подробно объясняется, что такое компьютер и зачем нужны разные его части. Готов посмотреть?",
    hub_lecture_poznanie_title: "Видео-урок: светофор",
    hub_lecture_poznanie_desc: "Правила дорожного движения подробнее",
    lecture_poznanie_video_title: "Видео-урок: светофор!",
    lecture_poznanie_explain: "Барыс приглашает тебя на видео-урок по познанию мира! Ты уже играл в нашу игру про дорожные знаки — а теперь посмотри мультфильм, где подробно рассказывается о светофоре и правилах дорожного движения. Это очень важно знать, чтобы быть в безопасности на улице. Готов посмотреть?",
    hub_lecture_muzyka_title: "Видео-урок: инструменты",
