    lecture_muzyka_video_title: "Видео-урок: инструменты!",
    lecture_muzyka_explain: "Барыс приглашает тебя на видео-урок по музыке! Ты уже играл в нашу игру про музыкальные инструменты — а теперь посмотри мультфильм, где показывают, как звучат разные инструменты. Готов посмотреть?",
    estestvo_title: "Естествознание",
