    back_estestvo: "← К играм по естествознанию",
    hub_plantparts_title: "Части растения",
    hub_plantparts_desc: "Корень, стебель, лист, цветок...",
    plantparts_game_title: "Части растения!",
    plantparts_game_sub: "Как называется эта часть растения? Найди картинку",
    plantparts_explain: "Барыс изучает растения! У каждого растения есть разные части: корень держит его в земле и пьёт воду, стебель поддерживает растение, листья ловят солнечный свет, а цветок превращается в плод с семенами внутри. Посмотри на название части и найди подходящую картинку. Готов изучать растения?",
    part_root: "КОРЕНЬ",
    part_stem: "СТЕБЕЛЬ",
    part_leaf: "ЛИСТ",
    part_flower: "ЦВЕТОК",
    part_fruit: "ПЛОД",
    part_seed: "СЕМЯ",
    hub_wildcult_title: "Дикое или культурное?",
    hub_wildcult_desc: "Растение само выросло, или его посадили?",
    wildcult_game_title: "Дикое или культурное?",
    wildcult_game_sub: "Это растение выросло само по себе, или его вырастили люди?",
    wildcult_explain: "Барыс гуляет по лугу и по саду! Дикорастущие растения растут сами по себе, без помощи человека — в лесу, в поле, на лугу. А культурные растения специально сажают и выращивают люди — на грядках, в садах, на полях. Посмотри на растение и подумай: оно дикое или культурное? Готов разобраться?",
    btn_wild: "Дикорастущее",
    btn_cultivated: "Культурное",
    hub_plantneeds_title: "Что нужно растению?",
    hub_plantneeds_desc: "Вода, свет, тепло — а игрушки?",
    plantneeds_game_title: "Что нужно растению?",
    plantneeds_game_sub: "Растению это нужно для жизни, или нет?",
    plantneeds_explain: "Барыс заботится о растениях! Чтобы расти, растению нужны особые условия: вода, солнечный свет и тепло. А вот игрушки, конфеты или машинки растению совсем не нужны! Посмотри на картинку и подумай: это нужно растению для жизни, или нет? Готов заботиться о растениях?",
    btn_needed: "Нужно",
    btn_not_needed: "Не нужно",
    hub_wildanimal_title: "Дикое или домашнее?",
    hub_wildanimal_desc: "Кто живёт в лесу, а кто — рядом с человеком?",
    wildanimal_game_title: "Дикое или домашнее?",
    wildanimal_game_sub: "Это животное дикое, или домашнее?",
    wildanimal_explain: "Барыс дружит и с дикими зверями, и с домашними животными! Дикие животные сами добывают себе еду и живут в лесу, в степи, без помощи человека. А домашних животных выращивает и кормит человек — они живут рядом с людьми, на ферме или дома. Посмотри на животное и подумай: оно дикое или домашнее? Готов разобраться?",
    btn_wildanimal: "Дикое",
    btn_domestic: "Домашнее",
    hub_adaptation_title: "Как звери готовятся к зиме?",
    hub_adaptation_desc: "Перелёт, запасы или спячка?",
    adaptation_game_title: "Как звери готовятся к зиме?",
    adaptation_game_sub: "Как это животное переживает зиму?",
    adaptation_explain: "Барыс изучает, как звери и птицы готовятся к холодной зиме! Одни птицы улетают в тёплые края, пока не наступит весна. Другие животные всё лето и осень запасают корм, чтобы хватило на всю зиму. А третьи просто засыпают глубоким сном на всю зиму — это называется спячка. Посмотри на животное и подумай, как оно переживает зиму. Готов узнать секреты зимовки?",
    btn_migration: "Улетает",
    btn_foodstore: "Запасает корм",
    btn_hibernate: "Спит всю зиму",
    hub_bodyparts_title: "Части тела",
    hub_bodyparts_desc: "Глаз, ухо, нос, рот...",
    bodyparts_game_title: "Части тела!",
    bodyparts_game_sub: "Как называется эта часть тела? Найди картинку",
    bodyparts_explain: "Барыс изучает своё тело! У каждой части тела есть своя работа: глаза помогают видеть, уши — слышать, нос — чувствовать запахи, рот — говорить и есть, руки — держать вещи, а ноги — ходить и бегать. Посмотри на название части тела и найди подходящую картинку. Готов изучать своё тело?",
