    hub_light_title: "Свет: природный или сделанный?",
    hub_light_desc: "Солнце светит само, а лампа?",
    light_game_title: "Свет: природный или сделанный?",
    light_game_sub: "Этот источник света природный, или его сделали люди?",
    light_explain: "Барыс изучает свет! Солнце, луна и молния светят сами по себе — это природные источники света. А лампочку, свечу и фонарик придумали и сделали люди — это искусственные источники света. Посмотри на картинку и подумай: этот свет природный, или искусственный? Готов разобраться со светом?",
    hub_sound_title: "Звук: природный или сделанный?",
    hub_sound_desc: "Лай собаки, а звонок?",
    sound_game_title: "Звук: природный или сделанный?",
    sound_game_sub: "Этот звук природный, или его создал человек?",
    sound_explain: "Барыс изучает звуки! Лай собаки, пение птиц и раскаты грома — это природные звуки, они возникают сами по себе. А звон колокольчика, музыка по радио и звук трубы придумали и создали люди — это искусственные звуки. Посмотри на картинку и подумай: этот звук природный, или искусственный? Готов разобраться со звуками?",
    btn_natural: "Природный",
    btn_artificial: "Искусственный",
    hub_magnet_title: "Притягивает магнит?",
    hub_magnet_desc: "Ключ, книга, яблоко — что притянет магнит?",
    magnet_game_title: "Притягивает магнит?",
    magnet_game_sub: "Магнит притянет этот предмет, или нет?",
    magnet_explain: "Барыс играет с магнитом! Магнит умеет притягивать только некоторые предметы — обычно те, что сделаны из металла, например ключ или гаечный ключ. А вот книгу, яблоко или воздушный шарик магнит не притянет — они не из металла. Посмотри на предмет и подумай: магнит его притянет, или нет? Готов проверить магнит?",
    btn_attracts: "Притянет",
    btn_not_attracts: "Не притянет",
