    computerdevices_game_sub: "Как называется это устройство? Найди картинку",
    computerdevices_explain: "Барыс изучает компьютер! У компьютера есть разные устройства: монитор показывает картинку, клавиатура нужна, чтобы печатать буквы, мышь помогает управлять курсором, а колонки воспроизводят звук. Посмотри на название и найди подходящую картинку. Готов изучать компьютер?",
