    hub_emergency_desc: "Пожарная, полиция, скорая — какой номер?",
    emergency_game_title: "Экстренные службы!",
    emergency_game_sub: "Какой номер у этой службы?",
    emergency_explain: "Барыс знает главные номера телефонов! Если случился пожар — звони 101, если нужна полиция — звони 102, а если кому-то плохо и нужна скорая помощь — звони 103. Есть и общий номер для любой беды — 112. Посмотри на картинку и выбери правильный номер. Готов запомнить важные номера?",
