    weekdays_game_title: "Дни недели!",
    weekdays_game_sub: "Расставь дни недели по порядку",
    weekdays_explain: "Барыс считает дни недели! Неделя всегда идёт в одном и том же порядке: понедельник, вторник, среда, четверг, пятница, суббота и воскресенье. Нажимай на дни по порядку, начиная с понедельника. Готов расставить дни недели?",
