    roadsigns_game_title: "Дорожные знаки!",
    roadsigns_game_sub: "Что означает этот знак? Прочитай и выбери картинку",
    roadsigns_explain: "Барыс изучает дорожные знаки! Каждый знак что-то означает: светофор регулирует движение, знак СТОП говорит остановиться, знак с детьми предупреждает о пешеходном переходе. Знание знаков помогает быть в безопасности на дороге. Посмотри на описание и найди нужный знак. Готов изучать дорожные знаки?",
