    hub_tens_desc: "Қай сан жетіспейді?",
    tens_explain: "Барыс бір-бірлеп емес, бірден ондықтармен санайды: 10, 20, 30... Сандар тізбегіне қара да, қайсысы жетіспейтінін тап. Ондықтармен санауға дайынсың ба?",
