    seasonplant_spring: "Өсімдіктер оянады, жас жапырақтар мен алғашқы гүлдер пайда болады",
    seasonplant_summer: "Өсімдіктер белсенді өседі, гүлдейді және жеміс береді",
    seasonplant_autumn: "Жапырақтар түсін өзгертіп, түседі, өсімдіктер қысқа дайындалады",
    seasonplant_winter: "Өсімдіктер тыныштық күйінде болады, өсу тоқтайды",
    hub_lecture_seasonplant_title: "Сабақ: Өсімдіктердің маусымдық өзгерістері",
    hub_lecture_seasonplant_desc: "Көктем, жаз, күз, қыс",
    lecture_seasonplant_title: "Сабақ: Өсімдіктердің маусымдық өзгерістері",
    lecture_seasonplant_sub: "Өсімдіктердің әр мезгілде қалай өзгеретінін біл",
    seasonplant_s1_title: "Мезгілдер және өсімдіктер",
    seasonplant_s1_text: "Барыс сені өсімдіктерді жыл бойы бақылауға шақырады! Әр мезгілде өсімдіктер мүлдем басқаша көрінеді — қазір қалай екенін білейік. Дайынсың ба?",
    seasonplant_s2_title: "Көктем",
    seasonplant_s2_text: "Көктемде өсімдіктер қысқы ұйқыдан оянады. Жас ашық жасыл жапырақтар пайда болып, алғашқы гүлдер ашылады.",
    seasonplant_s3_title: "Жаз",
    seasonplant_s3_text: "Жазда өсімдіктер ең тез өседі. Олар гүлдейді, шырынға толады және жеміс береді — табиғат үшін ең белсенді мезгіл.",
    seasonplant_s4_title: "Күз",
    seasonplant_s4_text: "Күзде жапырақтар түсін өзгертеді — сары, қызғылт сары және қызыл болады — содан кейін түседі. Осылай өсімдіктер суық қысқа дайындалады.",
    seasonplant_s5_title: "Қыс",
    seasonplant_s5_text: "Қыста өсімдіктер тыныштық күйінде болады: өсу тоқтайды, ағаштар жапырақсыз тұрып, көктемді күтеді.",
    seasonplant_s6_title: "Сен төрт мезгілді де білесің!",
    seasonplant_s6_text: "Барыс сені мақтан тұтады — енді сен көктемде, жазда, күзде және қыста өсімдіктерге не болатынын білесің! Ойында өзіңді тексеруге дайынсың ба?",
    waterprops_explain: "Барыс саған судың қасиеттерін айтады! Судың дәмі мен иісі жоқ, ол ағып, пішінін өзгерте алады. Тұжырымды оқы да, дұрыс па, бұрыс па екенін шеш. Дайынсың ба?",
    waterprops_game_title: "Судың қасиеттері",
    waterprops_game_sub: "Дұрыс па, бұрыс па?",
