    body_st_9: "Иіліп жүру арқаға пайдалы",
    body_st_10: "Қолды аптасына бір рет жуса жеткілікті",
    body_st_11: "Тіс ауырмаса, тазаламауға болады",
    body_st_12: "Жеке гигиена денсаулыққа әсер етпейді",
    hub_lecture_bodyhealth_title: "Сабақ: Дене және денсаулық",
    hub_lecture_bodyhealth_desc: "Скелет, бұлшықеттер, гигиена",
    lecture_bodyhealth_title: "Сабақ: Дене және денсаулық",
    lecture_bodyhealth_sub: "Дененің қалай құрылғанын және оны қалай күту керектігін біл",
    bodyhealth_s1_title: "Дене және денсаулық",
    bodyhealth_s1_text: "Барыс сені денеңнің қалай құрылғанын және оны қалай күтуге болатынын білуге шақырады! Бүгін скелет, бұлшықеттер, дене қалпы және жеке гигиена туралы сөйлесеміз. Дайынсың ба?",
    bodyhealth_s2_title: "Скелет",
    bodyhealth_s2_text: "Скелет — бүкіл дененің тірегі. Ол сүйектерден тұрады және пішінімізді сақтап, құламай тұруымызға көмектеседі.",
    bodyhealth_s3_title: "Бұлшықеттер",
    bodyhealth_s3_text: "Бұлшықеттер сүйектерге бекітілген. Олар жиырылғанда, біз қозғала аламыз — жүгіре, секіре, жаза, тіпті күле аламыз.",
    bodyhealth_s4_title: "Дұрыс дене қалпы",
    bodyhealth_s4_text: "Иіліп жүрсең, омыртқаға ауыр болады. Дұрыс дене қалпы — арқа түзу, иықтар кең жайылған — омыртқаны сау сақтауға көмектеседі.",
    bodyhealth_s5_title: "Жеке гигиена",
    bodyhealth_s5_text: "Тамақтан бұрын қол жуу микробтардан қорғайды, ал тісті күніне екі рет тазалау оны кариестен сақтайды. Жеке гигиена — денсаулықты сақтаудың қарапайым жолы.",
    bodyhealth_s6_title: "Сен өз денеңе қамқор бола аласың!",
    bodyhealth_s6_text: "Барыс сені мақтан тұтады — енді сен дененің қалай құрылғанын және оны қалай күту керектігін білесің! Ойында өзіңді тексеруге дайынсың ба?",
    ball_s1_title: "Доп — көңілді дос!",
    ball_s1_text: "Барыс бүгін доппен ойындарды көрсетеді! Доп шапшаңдықты, жылдамдықты және дәлдікті дамытады. Саған кез келген доп керек — үлкен немесе кіші, негізгісі қолыңа ыңғайлы ұстау. Ойнауға дайынсың ба?",
    ball_s2_title: "1-ойын: жоғары лақтыр да ұста",
    ball_s2_text: "Допты аз ғана жоғары лақтырып, екі қолыңмен ұста. Оңай шыға бастаса — допты ұстамас бұрын алақаныңды шапалақтап көр!",
    ball_s3_title: "2-ойын: доп шеңбермен",
    ball_s3_text: "Жанында достарың немесе туыстарың болса — шеңбер жасап тұрыңдар да, допты бір-біріңе лақтырыңдар. Доп жерге түспей неше рет ұшқанын дауыстап санаңдар!",
    ball_s4_title: "3-ойын: допты соғу",
    ball_s4_text: "Допты бір қолыңмен жерге соғып көр, нағыз баскетболшы сияқты. Баяу баста, содан кейін қатарынан неше рет шығатынын санап көр!",
    ball_s5_title: "4-ойын: нысанаға тигіз",
    ball_s5_text: "Себет немесе қорапты жерге қой да, аз қашықтықтан допты соған лақтырып көр. Әр реттен кейін сәл алысырақ тұр!",
    ball_s6_title: "Сен жарайсың!",
    ball_s6_text: "Барыс сені мақтан тұтады — бүгін сен шапшаңдық пен дәлдікті жаттықтырдың! Доппен жиірек ойна — бұл көңілді әрі денсаулыққа пайдалы.",
    hub_lecture_math_title: "Видео-сабақ: санау",
    hub_lecture_math_desc: "Сандар мен санау егжей-тегжейлі",
    lecture_math_video_title: "Видео-сабақ: санау!",
    lecture_math_explain: "Барыс сені математика бойынша видео-сабаққа шақырады! Сен біздің санау мен сандар туралы ойындарымызды ойнадың — енді осының бәрі тереңірек түсіндірілетін нағыз видео-сабақты қара. Сандарды білу және санай білу өмірде барлық жерде керек болады. Қарауға дайынсың ба?",
    hub_lecture_reading_title: "Видео-сабақ: дыбыстар",
    hub_lecture_reading_desc: "Дауысты және дауыссыз дыбыстар туралы толығырақ",
    lecture_reading_video_title: "Видео-сабақ: дыбыстар!",
    lecture_reading_explain: "Барыс сені грамотаға үйрету бойынша видео-сабаққа шақырады! Мұғалім дауысты мен дауыссыз дыбыстардың айырмашылығын егжей-тегжейлі түсіндіреді — сен бұл туралы біздің ойынымызды ойнадың, ал енді тағы да көбірек білесің. Қарауға дайынсың ба?"
