    hub_count_title: "Count and Find Out",
    hub_count_desc: "Count the objects on screen",
    hub_lecture_count_title: "Lesson: Counting",
    hub_lecture_count_desc: "Count and compare numbers",
    lecture_count_title: "Lesson: Counting",
    lecture_count_sub: "Learn to count objects and compare numbers",
    count_s1_title: "Counting",
    count_s1_text: "Barys invites you on a journey through numbers! Today we'll learn to count objects in order and compare which group has more. Ready to start?",
    count_s2_title: "Count in Order",
    count_s2_text: "When counting objects, say the numbers in order: one, two, three… and don't skip any object, or you'll lose count.",
    count_s3_title: "Example: Count the Apples",
    count_s3_text: "If there are 5 apples in the picture, we count: one, two, three, four, five. That's 5 apples!",
    count_s4_title: "More or Less?",
    count_s4_text: "To compare two groups of objects, count each one separately. The group with the bigger number is the one with more.",
    count_s5_title: "A Comparison Example",
    count_s5_text: "One basket has 4 pears, the other has 7 pears. 7 is more than 4, so the second basket has more pears.",
    count_s6_title: "You Can Count!",
    count_s6_text: "Barys is proud of you — now you can count objects and compare numbers! Ready to test yourself in the game?",
    hub_add_title: "Add and Find Out!",
    hub_add_desc: "Add two numbers correctly",
    hub_lecture_add_title: "Lesson: Addition",
    hub_lecture_add_desc: "How to combine groups of objects",
    lecture_add_title: "Lesson: Addition",
    lecture_add_sub: "Learn to add numbers",
    add_s1_title: "Addition",
    add_s1_text: "Barys knows the secret of addition! Addition is when we combine two groups of objects into one. Ready to find out how it works?",
    add_s2_title: "Combining Two Groups",
    add_s2_text: "If you have objects in one group and objects in another, put them together and count how many there are in total.",
    add_s3_title: "Example: Apples in Your Hands",
    add_s3_text: "One hand has 3 apples, the other has 2 apples. We add: 3 + 2 = 5. That's 5 apples in total!",
    add_s4_title: "The Plus Sign",
    add_s4_text: "The \"+\" sign means addition. When you see it between numbers, combine both groups and count the total.",
    add_s5_title: "Another Example",
    add_s5_text: "4 pencils in a case and 3 pencils on the table. 4 + 3 = 7. That's 7 pencils in total.",
    add_s6_title: "You Can Add!",
    add_s6_text: "Barys is proud of you — now you know how to add numbers! Ready to test yourself in the game?",
    hub_compare_title: "Compare Numbers",
    hub_compare_desc: "Which number is bigger?",
    hub_lecture_compare_title: "Lesson: Comparing Numbers",
    hub_lecture_compare_desc: "Greater than, less than, equal signs",
    lecture_compare_title: "Lesson: Comparing Numbers",
    lecture_compare_sub: "Learn to compare numbers and pick the sign",
    compare_s1_title: "Comparison",
    compare_s1_text: "Barys loves playing \"more or less\"! Today we'll learn to compare numbers and choose the right sign. Ready to start?",
    compare_s2_title: "Three Comparison Signs",
    compare_s2_text: "The \">\" sign means \"greater than,\" the \"<\" sign means \"less than,\" and the \"=\" sign means \"equal\" — the numbers are the same.",
    compare_s3_title: "Which Way the Sign Points",
    compare_s3_text: "A comparison sign always \"opens\" toward the bigger number and points its narrow tip at the smaller one. For example, 5 > 3.",
    compare_s4_title: "Example: Compare 4 and 7",
    compare_s4_text: "4 is less than 7, so we use the \"<\" sign: 4 < 7.",
    compare_s5_title: "Example: Compare 6 and 6",
    compare_s5_text: "The numbers are the same, so we put an \"=\" sign between them: 6 = 6.",
    compare_s6_title: "You Can Compare Numbers!",
    compare_s6_text: "Barys is proud of you — now you know the greater-than, less-than, and equal signs! Ready to test yourself in the game?",
    addition_game_title: "Add and Find Out!",
    addition_game_sub: "How many in total? Add them up and pick the answer",
    finish_msg: "Game complete! 🎉",
    play_again: "Play again",
    compare_game_title: "Compare the Numbers!",
    compare_game_sub: "Which side has more? Pick the right sign",
    hub_subtract_title: "Subtract and Find Out",
    hub_subtract_desc: "Take one number away from another",
    hub_lecture_subtract_title: "Lesson: Subtraction",
    hub_lecture_subtract_desc: "How to count what's left",
    lecture_subtract_title: "Lesson: Subtraction",
    lecture_subtract_sub: "Learn to subtract numbers",
    subtract_s1_title: "Subtraction",
    subtract_s1_text: "Barys will show you the opposite trick! Subtraction is when part of the objects go away, and we count how many are left. Ready to try?",
    subtract_s2_title: "Addition and Subtraction — Opposite Friends",
    subtract_s2_text: "Addition combines two groups, while subtraction, on the other hand, removes part of the objects. One is the opposite of the other.",
    subtract_s3_title: "Example: Birds Fly Away",
    subtract_s3_text: "5 birds were sitting on a branch. 2 birds flew away. We count: 5 − 2 = 3. 3 birds are left.",
    subtract_s4_title: "The Minus Sign",
    subtract_s4_text: "The \"−\" sign means subtraction. When you see it between numbers, count how many are left after part of the objects go away.",
    subtract_s5_title: "Another Example",
    subtract_s5_text: "There were 8 balloons, 3 popped. 8 − 3 = 5. 5 balloons are left.",
    subtract_s6_title: "You Can Subtract!",
    subtract_s6_text: "Barys is proud of you — now you know how to subtract numbers! Ready to test yourself in the game?",
    subtract_game_title: "Subtract and Find Out!",
    subtract_game_sub: "How many are left? Subtract and pick the answer",
