    hub_qwords_title: "Question Words",
    hub_qwords_desc: "Who? What? Which? How many?",
    hub_kazgenre_title: "What Genre Is This?",
    hub_kazgenre_desc: "Poem, tale, riddle",
    kazgenre_explain: "Barys is learning to tell apart different genres of Kazakh texts! A poem, a fairy tale, and a riddle each have their own features. Read the description and choose what this genre is called in Kazakh. Ready?",
    kazgenre_game_title: "What Genre Is This?",
    kazgenre_game_sub: "Which genre is described here?",
    kazgenre_desc_poem: "A text where the lines rhyme with each other",
    kazgenre_desc_tale: "A story with magic, where good often defeats evil",
    kazgenre_desc_riddle: "A short text where you need to guess what it's about",
    kazgenre_poem: "Өлең",
    kazgenre_tale: "Ертегі",
    kazgenre_riddle: "Жұмбақ",
    kazakh_q3_note: "This quarter's remaining topics require real spoken language — they can't be turned into a button-based game",
    qwords_game_title: "Question Words!",
    qwords_game_sub: "Which question fits the picture?",
    back_playroom: "← Back to Game Room",
    hub_memory_title: "Match the Pairs",
    hub_memory_desc: "Flip the cards and find matching pairs",
    memory_game_title: "Match the Pairs!",
    memory_game_sub: "Flip cards and find the matching pairs",
    moves_label: "Moves:",
    explain_heading: "What are we going to do?",
    speak_button: "🔊 Read aloud",
    count_explain: "Barys invites you on a journey through numbers! 🔢 Different objects live in the picture — count them in order: one, two, three… Don't make a mistake! Once you've counted, compare: which number turned out bigger, and which is smaller. The more carefully you count, the more stars you'll earn. Ready to set off?",
    addition_explain: "Barys knows a secret: addition is when we combine two groups of objects into one! If you have apples in one hand and apples in the other — put them together and count how many there are in total. Look carefully at both groups and don't forget to add everything you see. Ready to add numbers?",
    subtract_explain: "Now Barys will show you the opposite trick! Subtraction is when part of the objects go away, and we count how many are left. Addition and subtraction are like opposite friends: one combines, the other removes. Watch how many objects disappeared, and count what remains. Ready to try?",
    compare_explain: "Barys loves playing 'bigger or smaller'! To compare two numbers, count how many objects are in each group, then look — which has more, and which has fewer. They might even be equal! Count each group carefully before comparing. Ready to compare numbers?",
    letter_explain: "Barys whispers a secret to you: every letter has its own sound! Look at the big letter on the screen — now find the picture whose name starts with that same sound. Listen to how the first letter sounds in each word, and compare it with the one Barys showed you. Ready to search for letters?",
    word_explain: "Barys has prepared scattered letters for you! Every word is made of letters that stand one after another in order. Look at the picture — it will tell you which word to build. Tap the letters one by one until you get the whole word. Ready to build words?",
    vowel_explain: "Barys reveals the secret of sounds! Vowel sounds are sung freely, nothing blocks your mouth — ah-ah-ah, oh-oh-oh! But consonant sounds are pronounced with an obstacle — your lips, teeth, or tongue, like b or s. Listen to the letter and think: is it a vowel or a consonant? Ready to solve the sounds?",
    syllable_explain: "Barys knows how to clap out words! Every word can be split into small pieces — syllables. Try clapping the word out with your hands: however many times you clap, that's how many syllables there are! Look at the word on the screen and count how many syllables it has. Ready to clap out words?",
    hub_shapes_title: "Find the Line",
    hub_shapes_desc: "Point, line, segment, angle...",
    hub_lecture_shapes_title: "Lesson: Lines and Shapes",
    hub_lecture_shapes_desc: "Point, line, segment, angle in depth",
    lecture_shapes_title: "Lesson: Lines and Shapes",
    lecture_shapes_sub: "Learn to tell apart lines and simple shapes",
    shapes_s1_title: "Lines and Shapes",
    shapes_s1_text: "Barys is a real geometer! Today we'll learn the names of different lines and simple shapes. Ready to explore lines?",
    shapes_s2_title: "Point and Straight Line",
    shapes_s2_text: "A point is just a tiny dot on paper. A straight line goes evenly, without any bends, and has no beginning or end — it's endless in both directions.",
    shapes_s3_title: "Curve and Broken Line",
    shapes_s3_text: "A curve bends smoothly, like a winding road. A broken line zigzags with sharp angles, like a bolt of lightning!",
    shapes_s4_title: "Segment and Ray",
    shapes_s4_text: "A segment is part of a line with two ends: a beginning and an end. A ray is also part of a line, but it only has a beginning and no end — it goes on forever in one direction.",
    shapes_s5_title: "Angle",
    shapes_s5_text: "An angle is formed when two rays come out of the same point. That point is called the vertex of the angle.",
    shapes_s6_title: "You Know Lines and Shapes!",
    shapes_s6_text: "Barys is proud of you — now you can tell apart a point, straight line, curve, broken line, segment, ray, and angle! Ready to test yourself in the game?",
    shapes_game_title: "Find the Line!",
    shapes_game_sub: "What is this line or shape called? Find the matching picture",
    shapes_explain: "Barys is a real geometer! Lines have different names: a point is just a tiny dot, a straight line goes on evenly forever in both directions, while a broken line zigzags back and forth like lightning! Look at the name and find the matching line. Ready to study lines?",
    hub_flatsolid_title: "Flat or Solid?",
    hub_flatsolid_desc: "Ball, cube, can — what are they?",
    hub_lecture_flatsolid_title: "Lesson: Flat and Solid Shapes",
    hub_lecture_flatsolid_desc: "How to tell flat from solid",
    lecture_flatsolid_title: "Lesson: Flat and Solid Shapes",
    lecture_flatsolid_sub: "Learn to tell flat shapes apart from solid ones",
    flatsolid_s1_title: "Flat and Solid Shapes",
    flatsolid_s1_text: "Barys is showing different objects! Today we'll learn to tell flat shapes apart from solid ones. Ready to find out?",
    flatsolid_s2_title: "Flat Shapes",
    flatsolid_s2_text: "Flat shapes are like a drawing on paper — they have no thickness. For example, a circle or a square can be drawn on a single sheet.",
    flatsolid_s3_title: "Solid Shapes",
    flatsolid_s3_text: "Solid shapes are objects you can turn around in your hands — they have thickness and volume. For example, a ball (sphere) or a cube.",
    flatsolid_s4_title: "A Ball and a Circle Aren't the Same",
    flatsolid_s4_text: "A circle is flat — you can draw it. A ball is solid — round on every side, and you can roll it.",
    flatsolid_s5_title: "Check the Object",
    flatsolid_s5_text: "Look at an object: if you can pick it up and turn it around, it's solid. If it's like a picture on paper, it's flat. For example, a jar is solid, while a square on a sheet is flat.",
    flatsolid_s6_title: "You Can Tell Shapes Apart!",
    flatsolid_s6_text: "Barys is proud of you — now you can tell flat shapes apart from solid ones! Ready to test yourself in the game?",
    flatsolid_game_title: "Flat or Solid?",
    flatsolid_game_sub: "Is this object flat, like a sheet of paper, or solid, like a ball?",
    flatsolid_explain: "Barys is showing different objects! Flat shapes are like a drawing on paper, they have no thickness, like a circle or a square. Solid shapes have volume, you can turn them around in your hands, like a ball (sphere) or a cube. Look at the object and think: is it flat or solid? Ready to figure it out?",
    btn_flat: "Flat",
