    hub_half_title: "Half of a Number",
    hub_half_desc: "Split in half",
    half_explain: "Barys is learning to split a number in half! Look at the objects and count how many there would be if you split them into two equal parts. Ready to find the half?",
    half_game_title: "Half of a Number!",
    half_game_sub: "How many is this if split in half?",
    hub_clock_title: "What Time Is It?",
    hub_clock_desc: "Look at the clock face",
    clock_explain: "Barys is learning to tell time on a clock! Look at the clock face: the short dark hand points to the hour, and the long red hand always points to 12 — that means it's exactly on the hour, no minutes. Ready to find out what time it is?",
    clock_game_title: "What Time Is It?",
    clock_game_sub: "What time is it now?",
