    hub_coins_title: "Kazakhstani Coins",
    hub_coins_desc: "How many tenge?",
    coins_explain: "Barys is learning to recognize Kazakhstani coins! Kazakhstan has coins worth 1, 2, 5, 10, and 20 tenge. Look at the coin and figure out what's written on it. Ready to count money?",
