    alippe_letters1_game_title: "Find the Letter!",
    alippe_letters1_game_sub: "Which letter does this picture's name start with?",
    hub_alippe_letters2_title: "Find the Letter (Group 2)",
    hub_alippe_letters2_desc: "с, о, т, қ, ы, м, е, д, ш, ұ",
    alippe_letters2_explain: "Barys continues learning the alphabet! After the first group come these sounds: с, о, т, қ, ы, м, е, д, ш, ұ. Look at the picture and find which letter its name starts with. Ready to continue?",
    hub_prebukvar_title: "Sound, Syllable, Word, Sentence",
    hub_prebukvar_desc: "Let's discover the secrets of language",
    alippe_letters1_explain: "Barys is learning the Kazakh alphabet (Әліппе)! Following Akhmet Baitursynov's method, the most frequent sounds are taught first: а, р, л, н. Look at the picture and find which letter its name starts with. Ready to learn the alphabet?",
    kaz_direction_title: "Kazakh-medium — Grade 1",
