    anatili_desc: "Developing reading and writing skills",
    hub_vowelharmony_title: "Hard or Soft?",
    hub_vowelharmony_desc: "Vowel sounds",
    vowelharmony_explain: "Barys is learning that Kazakh vowels are either hard or soft! Hard vowels: а, о, ұ, ы. Soft vowels: ә, е, ө, ү, і. Look at the letter and figure out if it's hard or soft. Ready?",
