    hub_capital_title: "Capital Letter?",
    hub_capital_desc: "Names vs common words",
    capital_explain: "Barys is learning which words are written with a capital letter! People's names (Aigul), city names (Almaty), and animal nicknames (Aqbar) — with a capital. Ordinary words (қала — city, ит — dog) — with a lowercase letter. Read the word and choose the right answer. Ready?",
