    btn_lowercase: "Lowercase letter",
    kazakh_q4_note: "This quarter's remaining topics require real spoken language — they can't be turned into a button-based game",
    hub_wordharmony_title: "Hard Word or Soft Word?",
    hub_wordharmony_desc: "The law of vowel harmony",
    wordharmony_explain: "Barys is learning the law of vowel harmony! In a Kazakh word, all vowels are either all hard or all soft. Look at the word and figure out if it's a hard word or a soft word. Ready?",
    wordharmony_game_title: "Hard Word or Soft Word?",
