    btn_russian_direction: "Russian-medium instruction",
    btn_kazakh_direction: "Kazakh-medium instruction",
    rus_direction_title: "Russian-medium — Grade 1",
    rus_direction_grade2_title: "Russian-medium — Grade 2",
    rus_direction_desc: "Instruction in the Russian language",
    hub_lecture_kazakh_title: "Video Lesson: Sәlem!",
    hub_lecture_kazakh_desc: "First Kazakh words and phrases",
    lecture_kazakh_video_title: "Video Lesson: Sәlem!",
    lecture_kazakh_explain: "Barys invites you to a Kazakh language video lesson! The teacher will show you how to greet someone and ask their name in Kazakh — 'Sәlem! Seniñ atyñ kim?'. You've already played our games about Kazakh words, and now you'll hear real Kazakh speech. Ready to watch?",
    hub_lecture_estestvo_title: "Video Lesson: Plant Parts",
    hub_lecture_estestvo_desc: "Plants in depth",
    lecture_estestvo_video_title: "Video Lesson: Plant Parts!",
    lecture_estestvo_explain: "Barys invites you to a natural science video lesson! You've already played our game about parts of a plant — now watch a real video lesson where a teacher explains in detail about the root, stem, leaf, flower, and fruit. Ready to watch?",
    hub_lecture_digital_title: "Video Lesson: Devices",
    hub_lecture_digital_desc: "Computers in depth",
    lecture_digital_video_title: "Video Lesson: Devices!",
    lecture_digital_explain: "Barys invites you to a digital literacy video lesson! You've already played our game about computer devices — now watch a cartoon that explains in detail what a computer is and why its different parts are needed. Ready to watch?",
    hub_lecture_poznanie_title: "Video Lesson: Traffic Light",
    hub_lecture_poznanie_desc: "Road safety rules in depth",
    lecture_poznanie_video_title: "Video Lesson: Traffic Light!",
    lecture_poznanie_explain: "Barys invites you to a world cognition video lesson! You've already played our game about road signs — now watch a cartoon that explains in detail about the traffic light and road rules. This is very important to know to stay safe on the street. Ready to watch?",
    hub_lecture_muzyka_title: "Video Lesson: Instruments",
    hub_lecture_muzyka_desc: "Musical instruments in depth",
    lecture_muzyka_video_title: "Video Lesson: Instruments!",
    lecture_muzyka_explain: "Barys invites you to a music video lesson! You've already played our game about musical instruments — now watch a cartoon that shows how different instruments sound. Ready to watch?",
    estestvo_title: "Natural Science",
    estestvo_desc: "Plants, animals, nature",
    back_estestvo: "← Back to Natural Science games",
    hub_plantparts_title: "Parts of a Plant",
    hub_plantparts_desc: "Root, stem, leaf, flower...",
    plantparts_game_title: "Parts of a Plant!",
    plantparts_game_sub: "What is this part of a plant called? Find the picture",
    plantparts_explain: "Barys is studying plants! Every plant has different parts: the root holds it in the ground and drinks water, the stem supports the plant, the leaves catch sunlight, and the flower turns into a fruit with seeds inside. Look at the part's name and find the matching picture. Ready to study plants?",
