    part_seed: "SEED",
    hub_wildcult_title: "Wild or Cultivated?",
    hub_wildcult_desc: "Did it grow on its own, or was it planted?",
    wildcult_game_title: "Wild or Cultivated?",
    wildcult_game_sub: "Did this plant grow on its own, or did people grow it?",
    wildcult_explain: "Barys is walking through a meadow and a garden! Wild plants grow on their own, without human help — in forests, fields, meadows. Cultivated plants are specially planted and grown by people — in garden beds, orchards, farm fields. Look at the plant and think: is it wild or cultivated? Ready to figure it out?",
    btn_wild: "Wild",
    btn_cultivated: "Cultivated",
    hub_plantneeds_title: "What Does a Plant Need?",
    hub_plantneeds_desc: "Water, light, warmth — but toys?",
    plantneeds_game_title: "What Does a Plant Need?",
    plantneeds_game_sub: "Does a plant need this to live, or not?",
    plantneeds_explain: "Barys takes care of plants! To grow, a plant needs special conditions: water, sunlight, and warmth. But toys, candy, or toy cars are not needed by a plant at all! Look at the picture and think: does a plant need this to live, or not? Ready to take care of plants?",
    btn_needed: "Needed",
    btn_not_needed: "Not needed",
    hub_wildanimal_title: "Wild or Domestic?",
    hub_wildanimal_desc: "Who lives in the forest, and who lives with people?",
    wildanimal_game_title: "Wild or Domestic?",
    wildanimal_game_sub: "Is this animal wild, or domestic?",
    wildanimal_explain: "Barys is friends with both wild animals and domestic ones! Wild animals find their own food and live in forests, in the steppe, without human help. Domestic animals are raised and fed by people — they live near people, on a farm or at home. Look at the animal and think: is it wild or domestic? Ready to figure it out?",
    btn_wildanimal: "Wild",
    btn_domestic: "Domestic",
    hub_adaptation_title: "How Do Animals Prepare for Winter?",
    hub_adaptation_desc: "Migrate, store food, or hibernate?",
    adaptation_game_title: "How Do Animals Prepare for Winter?",
    adaptation_game_sub: "How does this animal survive the winter?",
    adaptation_explain: "Barys is studying how animals and birds prepare for cold winter! Some birds fly away to warm places until spring comes. Other animals spend all summer and autumn storing food to last through winter. And others simply fall into a deep sleep for the whole winter — this is called hibernation. Look at the animal and think about how it survives winter. Ready to learn winter secrets?",
    btn_migration: "Flies away",
    btn_foodstore: "Stores food",
    btn_hibernate: "Sleeps all winter",
    hub_bodyparts_title: "Body Parts",
    hub_bodyparts_desc: "Eye, ear, nose, mouth...",
    bodyparts_game_title: "Body Parts!",
    bodyparts_game_sub: "What is this body part called? Find the picture",
    bodyparts_explain: "Barys is studying his body! Every body part has its own job: eyes help you see, ears help you hear, the nose lets you smell, the mouth helps you talk and eat, hands hold things, and legs help you walk and run. Look at the body part's name and find the matching picture. Ready to study your body?",
    part_eye: "EYE",
    part_ear: "EAR",
    part_nose: "NOSE",
    part_mouth: "MOUTH",
    part_hand: "HAND",
    part_leg: "LEG",
    hub_lifestages_title: "Life Stages",
    hub_lifestages_desc: "From baby to elderly person",
    lifestages_game_title: "Life Stages!",
    lifestages_game_sub: "Put the stages of human life in order",
    lifestages_explain: "Barys is studying how a person grows! At first, a person is a tiny baby, then they grow up and become a child, then an adult, and at the end of life — an elderly person. Tap the pictures in order, from the earliest stage to the latest. Ready to learn the stages of life?",
    hub_humanneeds_title: "What Does a Child Need?",
    hub_humanneeds_desc: "Nutrition and rest — but toys?",
    humanneeds_game_title: "What Does a Child Need?",
    humanneeds_game_sub: "Does a child need this to grow, or not?",
    humanneeds_explain: "Barys takes care of children! To grow healthy and strong, a child needs proper nutrition and good rest — tasty healthy food and sound sleep. But toys, balls, or toy cars are not needed for growth, even though they're fun to play with! Look at the picture and think: does a child need this to grow, or not? Ready to check?",
    hub_spacetime_title: "Instruments and Time",
    hub_spacetime_desc: "Rocket, telescope, clock, calendar...",
    spacetime_game_title: "Instruments and Time!",
    spacetime_game_sub: "What is this object called? Find the picture",
    spacetime_explain: "Barys is studying space and time! To learn about space, scientists use rockets — to fly there, and telescopes — to look at distant stars. And to measure time, people use clocks, calendars, and hourglasses. Look at the name and find the matching picture. Ready to study instruments?",
    item_rocket: "ROCKET",
    item_telescope: "TELESCOPE",
    item_satellite: "SATELLITE",
    item_clock: "CLOCK",
    item_calendar: "CALENDAR",
    item_hourglass: "HOURGLASS",
    hub_light_title: "Light: Natural or Artificial?",
    hub_light_desc: "The sun shines by itself, but a lamp?",
    light_game_title: "Light: Natural or Artificial?",
    light_game_sub: "Is this light source natural, or did people make it?",
    light_explain: "Barys is studying light! The sun, the moon, and lightning shine on their own — these are natural light sources. But a lightbulb, a candle, and a flashlight were invented and made by people — these are artificial light sources. Look at the picture and think: is this light natural, or artificial? Ready to sort out light?",
    hub_sound_title: "Sound: Natural or Artificial?",
    hub_sound_desc: "A dog's bark, but a doorbell?",
    sound_game_title: "Sound: Natural or Artificial?",
    sound_game_sub: "Is this sound natural, or did a person create it?",
    sound_explain: "Barys is studying sounds! A dog's bark, birds singing, and thunder rolling are natural sounds — they happen on their own. But a bell ringing, music on the radio, and a trumpet sound were invented and created by people — these are artificial sounds. Look at the picture and think: is this sound natural, or artificial? Ready to sort out sounds?",
    btn_natural: "Natural",
    btn_artificial: "Artificial",
    hub_magnet_title: "Does a Magnet Attract It?",
    hub_magnet_desc: "Key, book, apple — which will a magnet attract?",
    magnet_game_title: "Does a Magnet Attract It?",
    magnet_game_sub: "Will a magnet attract this object, or not?",
    magnet_explain: "Barys is playing with a magnet! A magnet can only attract certain objects — usually ones made of metal, like a key or a wrench. But a book, an apple, or a balloon won't be attracted by a magnet — they're not made of metal. Look at the object and think: will the magnet attract it, or not? Ready to test the magnet?",
    btn_attracts: "Attracts",
    btn_not_attracts: "Doesn't attract",
