    hub_emergency_desc: "Fire, police, ambulance — which number?",
    emergency_game_title: "Emergency Services!",
    emergency_game_sub: "What is the number for this service?",
    emergency_explain: "Barys knows the important phone numbers! If there's a fire — call 101, if you need the police — call 102, and if someone is hurt and needs an ambulance — call 103. There's also a general number for any emergency — 112. Look at the picture and choose the correct number. Ready to learn the important numbers?",
