    hub_weekdays_desc: "Monday, Tuesday, Wednesday...",
    weekdays_game_title: "Days of the Week!",
    weekdays_game_sub: "Put the days of the week in order",
    weekdays_explain: "Barys is counting the days of the week! The week always goes in the same order: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, and Sunday. Tap the days in order, starting with Monday. Ready to put the days of the week in order?",
