    hub_roadsigns_desc: "Traffic light, STOP sign...",
    roadsigns_game_title: "Road Signs!",
    roadsigns_game_sub: "What does this sign mean? Read and pick the picture",
    roadsigns_explain: "Barys is learning road signs! Every sign means something: a traffic light controls movement, a STOP sign tells you to stop, a sign with children warns about a pedestrian crossing. Knowing signs helps you stay safe on the road. Look at the description and find the right sign. Ready to learn road signs?",
