    hub_count_title: "数一数吧",
    hub_count_desc: "数一数屏幕上的物品",
    hub_lecture_count_title: "课程：数数",
    hub_lecture_count_desc: "数数并比较数字",
    lecture_count_title: "课程：数数",
    lecture_count_sub: "学习数物品和比较数字",
    count_s1_title: "数数",
    count_s1_text: "巴雷斯邀请你一起踏上数字之旅！今天我们要学习按顺序数物品，还要比较哪组更多。准备好开始了吗？",
    count_s2_title: "按顺序数",
    count_s2_text: "数物品的时候，要按顺序说数字：一、二、三……不要漏掉任何一个，不然就数乱了。",
    count_s3_title: "例子：数苹果",
    count_s3_text: "如果图片上有5个苹果，我们数：一、二、三、四、五。一共5个苹果！",
    count_s4_title: "谁多谁少？",
    count_s4_text: "要比较两组物品，先把每组分别数一数。数字更大的那组，东西就更多。",
    count_s5_title: "比较的例子",
    count_s5_text: "一个篮子里有4个梨，另一个篮子里有7个梨。7比4多，所以第二个篮子里的梨更多。",
    count_s6_title: "你会数数啦！",
    count_s6_text: "巴雷斯为你感到骄傲——现在你会数物品、比较数字了！准备好在游戏里检验一下自己了吗？",
    hub_add_title: "加一加，找答案！",
    hub_add_desc: "正确地把两个数字相加",
    hub_lecture_add_title: "课程：加法",
    hub_lecture_add_desc: "怎么把两组东西合并",
    lecture_add_title: "课程：加法",
    lecture_add_sub: "学习把数字相加",
    add_s1_title: "加法",
    add_s1_text: "巴雷斯知道加法的秘密！加法就是把两组东西合并成一组。准备好来了解它是怎么算的了吗？",
    add_s2_title: "合并两组",
    add_s2_text: "如果你有一组东西，还有另一组东西，就把它们放在一起，数一数一共有多少个。",
    add_s3_title: "例子：手里的苹果",
    add_s3_text: "一只手里有3个苹果，另一只手里有2个苹果。我们来加一加：3 + 2 = 5。一共5个苹果！",
    add_s4_title: "加号",
    add_s4_text: "“+”表示加法。当你在数字中间看到它时，就要把两组合并起来，算出总数。",
    add_s5_title: "再来一个例子",
    add_s5_text: "文具盒里有4支铅笔，桌上有3支铅笔。4 + 3 = 7。一共7支铅笔。",
    add_s6_title: "你会加法啦！",
    add_s6_text: "巴雷斯为你感到骄傲——现在你知道怎么把数字加起来了！准备好在游戏里检验一下自己了吗？",
    hub_compare_title: "比较数字",
    hub_compare_desc: "哪个数字更大？",
    hub_lecture_compare_title: "课程：比较数字",
    hub_lecture_compare_desc: "大于、小于、等于符号",
    lecture_compare_title: "课程：比较数字",
    lecture_compare_sub: "学习比较数字并选出符号",
    compare_s1_title: "比较",
    compare_s1_text: "巴雷斯喜欢玩“谁多谁少”！今天我们要学习比较数字，选出正确的符号。准备好开始了吗？",
    compare_s2_title: "三种比较符号",
    compare_s2_text: "“>”表示“大于”，“<”表示“小于”，“=”表示“等于”——也就是两个数字一样。",
    compare_s3_title: "符号朝向哪边",
    compare_s3_text: "比较符号总是开口对着较大的数，尖端指向较小的数。比如，5 > 3。",
    compare_s4_title: "例子：比较4和7",
    compare_s4_text: "4比7小，所以用“<”：4 < 7。",
    compare_s5_title: "例子：比较6和6",
    compare_s5_text: "两个数字一样，所以中间用“=”：6 = 6。",
    compare_s6_title: "你会比较数字啦！",
    compare_s6_text: "巴雷斯为你感到骄傲——现在你认识大于号、小于号和等于号了！准备好在游戏里检验一下自己了吗？",
    addition_game_title: "加一加，找答案！",
    addition_game_sub: "一共有多少？加起来选出答案",
    finish_msg: "游戏完成！🎉",
    play_again: "再玩一次",
    compare_game_title: "比较数字！",
    compare_game_sub: "哪边更多？选择正确的符号",
    hub_subtract_title: "减一减，找答案",
    hub_subtract_desc: "从一个数字中减去另一个",
    hub_lecture_subtract_title: "课程：减法",
    hub_lecture_subtract_desc: "怎么数还剩下多少",
    lecture_subtract_title: "课程：减法",
    lecture_subtract_sub: "学习做减法",
    subtract_s1_title: "减法",
    subtract_s1_text: "巴雷斯要给你变个相反的魔术！减法就是当一部分东西离开了，我们数一数还剩下多少。准备好试试了吗？",
    subtract_s2_title: "加法和减法——一对相反的朋友",
    subtract_s2_text: "加法把两组合并起来，而减法正好相反，是拿走一部分东西。一个是另一个的反面。",
    subtract_s3_title: "例子：小鸟飞走了",
    subtract_s3_text: "树枝上原来有5只小鸟。飞走了2只。我们数一数：5 − 2 = 3。还剩3只小鸟。",
    subtract_s4_title: "减号",
    subtract_s4_text: "“−”表示减法。当你在数字中间看到它时，就要数一数东西离开一部分之后还剩多少。",
    subtract_s5_title: "再来一个例子",
    subtract_s5_text: "原来有8个气球，破了3个。8 − 3 = 5。还剩5个气球。",
    subtract_s6_title: "你会减法啦！",
    subtract_s6_text: "巴雷斯为你感到骄傲——现在你知道怎么做减法了！准备好在游戏里检验一下自己了吗？",
    subtract_game_title: "减一减，找答案！",
    subtract_game_sub: "还剩多少？减一减，选出答案",
