    memory_game_sub: "翻开卡片，找出相同的配对",
    moves_label: "步数：",
    explain_heading: "我们要做什么？",
    speak_button: "🔊 朗读",
    count_explain: "巴雷斯邀请你踏上数字之旅！🔢 图片里住着各种各样的东西——按顺序数一数：一、二、三……可别数错哦！数完之后再比一比：哪个数字更大，哪个更小。数得越仔细，得到的星星就越多。准备好出发了吗？",
    addition_explain: "巴雷斯知道一个秘密：加法就是把两组东西合并成一组！如果你一只手里有苹果，另一只手里也有苹果——把它们放在一起，数一数一共有多少个。仔细看两组东西，别忘了把看到的都加起来。准备好来加一加了吗？",
    subtract_explain: "现在巴雷斯要给你变个相反的魔术！减法就是当一部分东西离开了，我们数一数还剩下多少。加法和减法就像一对相反的朋友：一个是合并，一个是拿走。看看有多少东西消失了，再数一数剩下的。准备好试试了吗？",
    compare_explain: "巴雷斯喜欢玩「哪个更多、哪个更少」的游戏！要比较两个数字，先数一数每组有多少东西，然后看看——哪边更多，哪边更少。它们也可能一样多哦！比较之前要仔细数每一组。准备好比较数字了吗？",
    letter_explain: "巴雷斯悄悄告诉你一个秘密：每个字母都有自己的发音！看看屏幕上的大字母——现在找出名称以相同发音开头的图片。听一听每个词的第一个字母是怎么读的，和巴雷斯给你看的那个比一比。准备好找字母了吗？",
    word_explain: "巴雷斯给你准备了散落的字母！每个单词都是由按顺序排列的字母组成的。看看图片——它会告诉你需要拼出哪个单词。按顺序一个一个点击字母，直到拼出完整的单词。准备好拼单词了吗？",
    vowel_explain: "巴雷斯揭开了发音的秘密！元音可以自由地发出来，嘴巴不受任何阻碍——啊啊啊、噢噢噢！而辅音发音时会遇到阻碍——嘴唇、牙齿或舌头，比如b或s。听听这个字母，想一想：它是元音还是辅音？准备好破解发音了吗？",
    syllable_explain: "巴雷斯会用拍手来数单词！每个单词都可以分成小小的部分——音节。试着用手拍一拍这个词：拍几下，就有几个音节！看看屏幕上的单词，数一数它有几个音节。准备好拍一拍单词了吗？",
    hub_shapes_title: "找线条",
    hub_shapes_desc: "点、直线、线段、角……",
    hub_lecture_shapes_title: "课程：线和图形",
    hub_lecture_shapes_desc: "点、直线、线段、角详解",
    lecture_shapes_title: "课程：线和图形",
    lecture_shapes_sub: "学习分辨线和简单图形",
    shapes_s1_title: "线和图形",
    shapes_s1_text: "巴雷斯是个真正的几何学家！今天我们要学习各种线和简单图形的名字。准备好来了解线了吗？",
    shapes_s2_title: "点和直线",
    shapes_s2_text: "点就是纸上一个很小的点。直线笔直地延伸，没有弯曲，也没有起点和终点——它朝两个方向无限延伸。",
    shapes_s3_title: "曲线和折线",
    shapes_s3_text: "曲线像蜿蜒的道路一样平滑地弯曲。折线则像闪电一样，带着尖锐的角来回转折！",
    shapes_s4_title: "线段和射线",
    shapes_s4_text: "线段是直线的一部分，有两个端点：起点和终点。射线也是直线的一部分，但它只有起点没有终点——朝一个方向无限延伸。",
    shapes_s5_title: "角",
    shapes_s5_text: "两条射线从同一个点发出，就形成了角。这个点叫做角的顶点。",
    shapes_s6_title: "你会认线和图形啦！",
    shapes_s6_text: "巴雷斯为你感到骄傲——现在你能分清点、直线、曲线、折线、线段、射线和角了！准备好在游戏里检验一下自己了吗？",
    shapes_game_title: "找线条！",
    shapes_game_sub: "这条线或图形叫什么名字？找出匹配的图片",
    shapes_explain: "巴雷斯是真正的几何学家！线条有不同的名字：点只是一个小小的点，直线朝两个方向笔直延伸，没有尽头，而折线像闪电一样来回弯折！看看名字，找出与之匹配的线条。准备好学习线条了吗？",
    hub_flatsolid_title: "平面还是立体？",
    hub_flatsolid_desc: "球、方块、罐子——它们是什么样的？",
    hub_lecture_flatsolid_title: "课程：平面图形和立体图形",
    hub_lecture_flatsolid_desc: "怎么分辨平面和立体",
    lecture_flatsolid_title: "课程：平面图形和立体图形",
    lecture_flatsolid_sub: "学习分辨平面图形和立体图形",
    flatsolid_s1_title: "平面图形和立体图形",
    flatsolid_s1_text: "巴雷斯要给你看不同的东西！今天我们要学习分辨平面图形和立体图形。准备好来了解一下了吗？",
    flatsolid_s2_title: "平面图形",
    flatsolid_s2_text: "平面图形就像纸上画的画一样，没有厚度。比如圆形或正方形，一张纸就能画出来。",
    flatsolid_s3_title: "立体图形",
    flatsolid_s3_text: "立体图形是可以拿在手里转动的东西，它们有厚度和体积。比如球或正方体。",
    flatsolid_s4_title: "球和圆不是一回事",
    flatsolid_s4_text: "圆是平的，可以画出来。球是立体的，每个方向都是圆的，可以滚动。",
    flatsolid_s5_title: "检查一下东西",
    flatsolid_s5_text: "看看这个东西：如果能拿在手里转动，它就是立体的。如果它像纸上的图画，它就是平面的。比如，罐子是立体的，纸上的正方形是平面的。",
    flatsolid_s6_title: "你会分辨图形啦！",
    flatsolid_s6_text: "巴雷斯为你感到骄傲——现在你会分辨平面图形和立体图形了！准备好在游戏里检验一下自己了吗？",
    flatsolid_game_title: "平面还是立体？",
    flatsolid_game_sub: "这个物体是像纸一样平的，还是像球一样立体的？",
    flatsolid_explain: "巴雷斯展示了各种各样的物体！平面图形就像纸上的画，没有厚度，比如圆形或正方形。立体图形是有体积的，你可以用手转动它们，比如球（球体）或方块（立方体）。看看这个物体，想一想：它是平面的还是立体的？准备好来分辨了吗？",
