    wildcult_explain: "巴雷斯在草地和花园里散步！野生植物是自己生长的，不需要人的帮助——在森林里、田野里、草地上。栽培植物是人们专门种植和培育的——在菜园里、果园里、农田里。看看这株植物，想一想：它是野生的还是栽培的？准备好来分辨了吗？",
