    plantneeds_explain: "巴雷斯在照顾植物！为了生长，植物需要特殊的条件：水、阳光和温暖。但是玩具、糖果或玩具车植物完全不需要！看看图片，想一想：植物生长需要这个吗？准备好照顾植物了吗？",
