    wildanimal_game_sub: "这只动物是野生的，还是家养的？",
    wildanimal_explain: "巴雷斯和野生动物、家养动物都是朋友！野生动物自己寻找食物，生活在森林、草原里，不需要人的帮助。家养动物是人们饲养和喂养的——它们生活在人们身边，在农场或家里。看看这只动物，想一想：它是野生的还是家养的？准备好来分辨了吗？",
