    roadsigns_explain: "巴雷斯在学习交通标志！每个标志都有它的意思：红绿灯用来指挥交通，停车标志告诉你要停下来，带有儿童图案的标志提醒你注意人行横道。认识这些标志能帮助你在路上更安全。看看描述，找出正确的标志。准备好学习交通标志了吗？",
    sign_traffic_light: "红绿灯",
