    body_st_11: "牙齿不疼就不用刷",
    body_st_12: "个人卫生不影响健康",
    hub_lecture_bodyhealth_title: "课程：身体与健康",
    hub_lecture_bodyhealth_desc: "骨骼、肌肉、卫生",
    lecture_bodyhealth_title: "课程：身体与健康",
    lecture_bodyhealth_sub: "了解身体是如何运作的，以及如何照顾它",
    bodyhealth_s1_title: "身体与健康",
    bodyhealth_s1_text: "巴雷斯邀请你了解你的身体是如何运作的，以及如何照顾它！今天我们要聊聊骨骼、肌肉、坐姿和个人卫生。准备好了吗？",
    bodyhealth_s2_title: "骨骼",
    bodyhealth_s2_text: "骨骼支撑着我们整个身体。它由骨头组成，帮助我们保持体形，站立，而不会瘫成一团。",
    bodyhealth_s3_title: "肌肉",
    bodyhealth_s3_text: "肌肉连接在骨头上。当它们收缩时，我们就能活动——跑步、跳跃、写字，甚至微笑。",
    bodyhealth_s4_title: "良好的坐姿",
    bodyhealth_s4_text: "驼背会给脊柱带来负担。良好的姿势——背部挺直，肩膀放松——有助于保持脊柱健康。",
    bodyhealth_s5_title: "个人卫生",
    bodyhealth_s5_text: "饭前洗手能保护你不受细菌侵害，每天刷两次牙能保护牙齿不蛀。个人卫生是保持健康的简单方法。",
    bodyhealth_s6_title: "你懂得照顾自己的身体啦！",
    bodyhealth_s6_text: "巴雷斯为你感到骄傲——现在你知道身体是如何运作的，以及如何照顾它了！准备好在游戏里检验一下自己了吗？",
    ball_s1_title: "球是个有趣的朋友！",
    ball_s1_text: "今天巴雷斯要给你展示球类游戏！球能锻炼灵活性、速度和准确性。你需要任意一个球——大的小的都可以，只要拿着舒服就行。准备好玩了吗？",
    ball_s2_title: "游戏一：抛球接球",
    ball_s2_text: "把球轻轻往上抛，用双手接住。等这个动作轻松了——试着在接球前拍一下手！",
    ball_s3_title: "游戏二：传球围圈",
    ball_s3_text: "如果身边有朋友或家人——围成一圈，互相传球。大声数一数球传了多少次没有掉到地上！",
    ball_s4_title: "游戏三：拍球",
    ball_s4_text: "试着用一只手把球拍到地上，像真正的篮球运动员一样。先慢慢开始，然后数一数能连续拍多少次！",
    ball_s5_title: "游戏四：投中目标",
    ball_s5_text: "在地上放一个篮子或箱子，试着从不远处把球投进去。每次都往后退一点点！",
    ball_s6_title: "你真棒！",
    ball_s6_text: "巴雷斯为你感到骄傲——今天你锻炼了灵活性和准确性！多和球一起玩吧——这既有趣又有益健康。",
