    hub_lecture_count_desc: "Санаймиз ва сонларни солиштирамиз",
    lecture_count_title: "Дарс: Санаш",
    lecture_count_sub: "Нарсаларни санашни ва сонларни солиштиришни ўрган",
    count_s1_title: "Санаш",
    count_s1_text: "Барыс сени сонлар дунёси бўйлаб саёҳатга таклиф қилади! Бугун нарсаларни тартиб билан санашни ва қайси гуруҳда кўпроқ эканини солиштиришни ўрганамиз. Бошлашга тайёрмисан?",
    count_s2_title: "Тартиб билан сана",
    count_s2_text: "Нарсаларни санаганда, сонларни тартиб билан айт: бир, икки, уч… ва бирорта нарсани ҳам ўтказиб юборма, акс ҳолда адашиб қоласан.",
    count_s3_title: "Мисол: олмаларни санаб чиқ",
    count_s3_text: "Агар расмда 5 та олма бўлса, санаймиз: бир, икки, уч, тўрт, беш. Жами 5 та олма!",
    count_s4_title: "Кўпми ёки камми?",
    count_s4_text: "Икки гуруҳ нарсани солиштириш учун ҳар бирини алоҳида санаб чиқ. Сони кўпроқ гуруҳ — нарсалари кўпроқ гуруҳ.",
    count_s5_title: "Солиштириш мисоли",
    count_s5_text: "Бир саватда 4 та нок, иккинчисида — 7 та нок. 7 сони 4 дан кўп, демак иккинчи саватда нок кўпроқ.",
    count_s6_title: "Сен санай оласан!",
    count_s6_text: "Барыс сен билан фахрланади — энди сен нарсаларни санай ва сонларни солиштира оласан! Ўйинда ўзингни синаб кўришга тайёрмисан?",
    hub_add_title: "Қўшиб ол",
    hub_add_desc: "Икки сонни тўғри қўш",
    hub_lecture_add_title: "Дарс: Қўшиш",
    hub_lecture_add_desc: "Гуруҳларни қандай бирлаштириш",
    lecture_add_title: "Дарс: Қўшиш",
    lecture_add_sub: "Сонларни қўшишни ўрган",
    add_s1_title: "Қўшиш",
    add_s1_text: "Барысда қўшиш сири бор! Қўшиш — бу икки гуруҳ буюмни битта гуруҳга бирлаштириш. Бу қандай ишлашини билишга тайёрмисан?",
    add_s2_title: "Икки гуруҳни бирлаштирамиз",
    add_s2_text: "Агар бир гуруҳда буюмларинг, иккинчисида ҳам буюмларинг бўлса — уларни қўшиб, жамики нечта бўлганини сана.",
    add_s3_title: "Мисол: қўлдаги олмалар",
    add_s3_text: "Бир қўлда 3 та олма, иккинчисида — 2 та олма. Қўшамиз: 3 + 2 = 5. Жами 5 та олма!",
    add_s4_title: "Қўшиш белгиси",
    add_s4_text: "«+» белгиси қўшишни билдиради. Уни сонлар орасида кўрганингда, икки гуруҳни бирлаштириб, йиғиндисини санаш керак.",
    add_s5_title: "Яна бир мисол",
    add_s5_text: "Пеналда 4 та қалам, столда 3 та қалам. 4 + 3 = 7. Жами 7 та қалам.",
    add_s6_title: "Сен қўша оласан!",
    add_s6_text: "Барыс сен билан фахрланади — энди сен сонларни қўша оласан! Ўйинда ўзингни синаб кўришга тайёрмисан?",
