    lecture_compare_title: "Дарс: Сонларни солиштириш",
    lecture_compare_sub: "Сонларни солиштиришни ва белгини танлашни ўрган",
    compare_s1_title: "Солиштириш",
    compare_s1_text: "Барыс «кўпми ёки камми» ўйинини яхши кўради! Бугун сонларни солиштиришни ва тўғри белгини танлашни ўрганамиз. Бошлашга тайёрмисан?",
    compare_s2_title: "Учта солиштириш белгиси",
    compare_s2_text: "«>» белгиси «кўп» дегани, «<» белгиси «кам» дегани, «=» белгиси эса «тенг» дегани — яъни сонлар бир хил.",
    compare_s3_title: "Белги қаёққа қарайди",
    compare_s3_text: "Солиштириш белгиси ҳамиша кенг томони билан катта сонга, тор томони билан кичик сонга «қарайди». Масалан, 5 > 3.",
    compare_s4_title: "Мисол: 4 ва 7 ни солиштир",
    compare_s4_text: "4 сони 7 дан кичик, шунинг учун «<» белгисини қўямиз: 4 < 7.",
    compare_s5_title: "Мисол: 6 ва 6 ни солиштир",
    compare_s5_text: "Сонлар бир хил, демак ораларига «=» белгисини қўямиз: 6 = 6.",
    compare_s6_title: "Сен сонларни солиштира оласан!",
    compare_s6_text: "Барыс сен билан фахрланади — энди сен кўп, кам ва тенг белгиларини биласан! Ўйинда ўзингни синаб кўришга тайёрмисан?",
