    hub_kazgenre_title: "Бу қайси жанр?",
    hub_kazgenre_desc: "Шеър, эртак, топишмоқ",
    kazgenre_explain: "Барыс қозоқ тилидаги турли жанрдаги матнларни фарқлашни ўрганяпти! Шеър, эртак ва топишмоқнинг — ҳар бирининг ўз хусусияти бор. Тавсифни ўқи ва бу жанр қозоқча қандай аталишини топ. Тайёрмисан?",
