    spacetime_game_sub: "Бу нарса қандай аталади? Расмни топ",
    spacetime_explain: "Барыс коинот ва вақтни ўрганяпти! Коинот ҳақида билиш учун олимлар ракетадан фойдаланади — у ерга учиш учун, ва телескопдан — узоқ юлдузларни кўриш учун. Вақтни ўлчаш учун эса одамлар соат, календарь ва қум соатдан фойдаланади. Номга қара ва мос расмни топ. Асбобларни ўрганишга тайёрмисан?",
