    light_explain: "Барыс ёруғликни ўрганяпти! Қуёш, ой ва чақмоқ ўз-ўзидан ёритади — булар табиий ёруғлик манбалари. Лампочка, шам ва фонарни эса одамлар ўйлаб топиб ясаган — булар сунъий ёруғлик манбалари. Расмга қара ва ўйла: бу ёруғлик табиийми ёки сунъийми? Ёруғликни аниқлашга тайёрмисан?",
    hub_sound_title: "Товуш: табиий ёки сунъий?",
    hub_sound_desc: "Итнинг вовуллаши, қўнғироқ-чи?",
    sound_game_title: "Товуш: табиий ёки сунъий?",
    sound_game_sub: "Бу товуш табиийми ёки уни инсон яратганми?",
    sound_explain: "Барыс товушларни ўрганяпти! Итнинг вовуллаши, қушларнинг сайраши ва момақалдироқ — булар табиий товушлар, улар ўз-ўзидан пайдо бўлади. Қўнғироқ товуши, радиодаги мусиқа ва карнай товуши эса одамлар ўйлаб топиб яратган — булар сунъий товушлар. Расмга қара ва ўйла: бу товуш табиийми ёки сунъийми? Товушларни аниқлашга тайёрмисан?",
