    hub_truefalse_title: "Дуруст ё нодуруст?",
    hub_truefalse_desc: "Баробариро санҷ",
    truefalse_game_title: "Дуруст ё нодуруст?",
    truefalse_game_sub: "Ба баробарӣ нигоҳ кун — он дуруст аст ё не?",
    truefalse_explain: "Барыс баробариҳоро месанҷад! Баъзан рақамҳо дуруст ҷамъ мешаванд, баъзан бошад қасдан хато карда мешавад. Ба мисоли дар экран нигоҳ кун ва фикр кун: тарафи чап ва рости аломати «=» як рақами якхела медиҳанд? Агар ҳа — ин баробарии дуруст аст, агар не — нодуруст. Омодаи санҷидани рақамҳо ҳастӣ?",
    btn_true: "Дуруст",
    btn_false: "Нодуруст",
    hub_pattern_title: "Қонунро ёб",
    hub_pattern_desc: "Рақами баъдӣ кадом аст?",
    pattern_game_title: "Қонунро ёб!",
    pattern_game_sub: "Ба рақамҳо нигоҳ кун — баъдӣ кадом аст?",
    pattern_explain: "Барыс муаммоҳои рақамиро дӯст медорад! Дар силсилаи рақамҳо тартиби пинҳонӣ ҳаст — масалан, ҳар рақами баъдӣ метавонад аз қаблӣ 2 адад бештар бошад. Ба рақамҳои дар экран нигоҳ кун ва бифаҳм, ки рақами баъдӣ кадом бояд бошад. Омодаи ёфтани қонунҳо ҳастӣ?",
    hub_symbolseq_title: "Қаторро идома деҳ",
    hub_symbolseq_desc: "Расми баъдӣ кадом аст?",
    hub_tens_title: "Даҳякҳо",
    hub_tens_desc: "Кадом рақам намерасад?",
    tens_explain: "Барыс на якка-якка, балки бевосита бо даҳякҳо мешуморад: 10, 20, 30... Ба занҷири рақамҳо нигоҳ кун ва бифаҳм, ки кадомаш намерасад. Омодаи бо даҳякҳо шумурдан ҳастӣ?",
    tens_game_title: "Даҳякҳо!",
    tens_game_sub: "Дар занҷир кадом рақам намерасад?",
    math_q2_note: "Мавзӯъҳои «Нисфи адад», «Ченкунии дарозӣ/вазн/ҳаҷм», «Вақт аз рӯи соат»-и ин семестр ҳанӯз сохта нашудаанд",
    hub_half_title: "Нисфи адад",
    hub_half_desc: "Ба ду тақсим кун",
    half_explain: "Барыс ададро ба ду нисф тақсим карданро меомӯзад! Ба чизҳо нигоҳ кун ва шумор, ки агар онҳоро ба ду ҳиссаи баробар тақсим кунӣ, чанд адад мешавад. Омодаи ёфтани нисф ҳастӣ?",
    half_game_title: "Нисфи адад!",
    half_game_sub: "Агар ба ду тақсим кунем, чанд мешавад?",
    hub_clock_title: "Соат чанд аст?",
    hub_clock_desc: "Ба соат нигоҳ кун",
    clock_explain: "Барыс аз рӯи соат вақтро муайян карданро меомӯзад! Ба рӯи соат нигоҳ кун: ақрабаки кӯтоҳи торик соатро нишон медиҳад, ақрабаки дарози сурх ҳамеша ба 12 нигаронида шудааст — яъне вақт дуруст аст, бе дақиқа. Омодаи фаҳмидани соат ҳастӣ?",
    clock_game_title: "Соат чанд аст?",
    clock_game_sub: "Ҳозир соат чанд аст?",
    hub_measure_title: "Бо чӣ ченем?",
    hub_measure_desc: "Дарозӣ, вазн ё ҳаҷм?",
    measure_explain: "Барыс интихоби ченаки дурустро меомӯзад! Қалам бо дарозӣ, себ бо вазн, оби дар шиша бошад бо ҳаҷм ченида мешавад. Ба чиз нигоҳ кун ва бифаҳм, ки онро бо чӣ мечанд. Омодаӣ?",
    measure_game_title: "Бо чӣ ченем?",
    measure_game_sub: "Ин чиз бо чӣ чен карда мешавад?",
    measure_length: "Дарозӣ (см)",
    measure_mass: "Вазн (кг)",
    measure_volume: "Ҳаҷм (л)",
    hub_coins_title: "Тангаҳои Қазоқистон",
    hub_coins_desc: "Чанд тенге?",
    coins_explain: "Барыс тангаҳои Қазоқистонро шинохтанро меомӯзад! Дар Қазоқистон тангаҳои 1, 2, 5, 10 ва 20 тенгегӣ мавҷуданд. Ба танга нигоҳ кун ва бифаҳм, ки дар он чӣ навишта шудааст. Омодаи шумурдани пул ҳастӣ?",
    coins_game_title: "Тангаҳои Қазоқистон!",
    coins_game_sub: "Дар ин танга чанд тенге навишта шудааст?",
    hub_teens_title: "Ададҳои 11-20",
    hub_teens_desc: "Даҳяк ва воҳидҳо",
    teens_explain: "Барыс ададҳои аз даҳ калонтарро шумурданро меомӯзад! Ҳар яке аз чунин ададҳо аз як даҳяк ва якчанд воҳиди алоҳида иборат аст. Ба доирачаҳо нигоҳ кун ва ададди дурустро ёб. Омодаи шумурдан ҳастӣ?",
    teens_game_title: "Ададҳои 11-20!",
    teens_game_sub: "Ин чанд аст?",
    math_q4_note2: "Мавзӯи «Маҷмӯаҳо»-и ин семестр ҳанӯз сохта нашудааст",
    hub_sets_title: "Маҷмӯаҳоро муқоиса кун",
    hub_sets_desc: "Дар куҷо бештар?",
    sets_explain: "Барыс гурӯҳҳои чизҳоро муқоиса карданро меомӯзад! Ба ду гурӯҳ нигоҳ кун — дар кадомаш чиз бештар, дар кадомаш камтар, ё баробаранд? Омодаи муқоиса кардан ҳастӣ?",
    sets_game_title: "Маҷмӯаҳоро муқоиса кун!",
    sets_game_sub: "Дар кадом гурӯҳ чиз бештар аст?",
    sets_a_more: "Дар чап бештар",
    sets_equal: "Баробар",
    sets_b_more: "Дар рост бештар",
    hub_movement_title: "Ин чӣ хел ҳаракат мекунад?",
    hub_movement_desc: "Мепарад, шино мекунад, ё мегардад?",
    movement_explain: "Барыс тарзҳои гуногуни ҳаракатро меомӯзад! Паррандаҳо мепаранд, моҳиҳо шино мекунанд, мошинҳо бошанд рӯи замин мераванд. Ба расм нигоҳ кун ва бифаҳм, ки ин чиз ё мавҷудот чӣ хел ҳаракат мекунад. Омодаӣ?",
    movement_game_title: "Ин чӣ хел ҳаракат мекунад?",
