    hub_earthshape_title: "Шакли Замин",
    hub_earthshape_desc: "Мисли тӯб мудаввар?",
    earthshape_explain: "Барыс мефаҳмад, ки сайёраи мо чӣ шакл дорад! Замин мисли тӯб мудаввар аст — олимон чунин шаклро кура ё сфера меноманд. Глобус модели хурди Замин аст, он ҳам мудаввар аст. Ба чиз нигоҳ кун ва бифаҳм, ки он мудаввар аст ё не. Омодаӣ?",
    earthshape_game_title: "Шакли Замин!",
