    btn_not_round: "Мудаввар нест",
    estestvo_q3_note2: "Мавзӯъҳои «Гармӣ», «Барқ»-и ин семестр ҳанӯз сохта нашудаанд",
    hub_heat_title: "Гарм ё сард?",
    hub_heat_desc: "Чӣ гарм, чӣ сард?",
    heat_explain: "Барыс мефаҳмад, ки чӣ гармӣ медиҳад! Оташ, шамъ ва офтоб — гарманд, онҳо гарм мекунанд. Барф, ях ва шаб — сарданд. Ба расм нигоҳ кун ва бифаҳм, ки он гарм аст ё сард. Омодаӣ?",
