    lecture_estestvo_explain: "Барыс туро ба дарси видеоии табиатшиносӣ даъват мекунад! Ту бозии моро дар бораи қисмҳои растанӣ бозидӣ — ҳоло дарси видеоии воқеиро бубин, ки муаллим дар бораи реша, поя, барг, гул ва мева муфассал нақл мекунад. Омодаи тамошо кардан ҳастӣ?",
