    hub_lecture_poznanie_title: "Дарси видеоӣ: чароғи роҳ",
    hub_lecture_poznanie_desc: "Қоидаҳои ҳаракати роҳ муфассал",
    lecture_poznanie_video_title: "Дарси видеоӣ: чароғи роҳ!",
    lecture_poznanie_explain: "Барыс туро ба дарси видеоии маърифати ҷаҳон даъват мекунад! Ту бозии моро дар бораи аломатҳои роҳ бозидӣ — ҳоло мультфильмеро бубин, ки дар бораи чароғи роҳ ва қоидаҳои ҳаракати роҳ муфассал нақл мекунад. Донистани ин барои бехатар буданат дар кӯча хеле муҳим аст. Омодаи тамошо кардан ҳастӣ?",
    hub_lecture_muzyka_title: "Дарси видеоӣ: созҳо",
    hub_lecture_muzyka_desc: "Созҳои мусиқӣ муфассал",
