    lecture_muzyka_explain: "Барыс туро ба дарси видеоии мусиқӣ даъват мекунад! Ту бозии моро дар бораи созҳои мусиқӣ бозидӣ — ҳоло мультфильмеро бубин, ки нишон медиҳад, ки созҳои гуногун чӣ тавр садо медиҳанд. Омодаи тамошо кардан ҳастӣ?",
