    plantparts_explain: "Барыс растаниҳоро меомӯзад! Ҳар растанӣ қисмҳои гуногун дорад: реша онро дар замин нигоҳ медорад ва об менӯшад, поя растаниро дастгирӣ мекунад, баргҳо нури офтобро мегиранд, гул бошад ба меваи дар дараш тухм ҳаст табдил меёбад. Ба номи қисм нигоҳ кун ва расми мувофиқро ёб. Омодаи омӯхтани растаниҳо ҳастӣ?",
