    ball_s3_text: "Агар дар наздикӣ дӯстон ё хешовандон бошанд — дар доира биистед ва тӯбро ба якдигар парто. Бо овоз баланд шумор, ки тӯб чанд бор бе афтодан ба замин гузашт!",
