    ball_s4_text: "Тӯбро бо як даст ба замин зарба зада кӯшиш кун, мисли бозигари воқеии баскетбол. Оҳиста сар кун, баъд шумор, ки паси ҳам чанд бор мешавад!",
    ball_s5_title: "Бозии 4: ба нишон зан",
    ball_s5_text: "Сабад ё қуттиро ба замин гузор ва аз масофаи начандон дур тӯбро ба он парто кӯшиш кун. Ҳар дафъа андак дуртар рав!",
    ball_s6_title: "Ту офаринӣ!",
    ball_s6_text: "Барыс ба ту ифтихор мекунад — имрӯз ту чолокӣ ва дақиқиро машқ кардӣ! Бо тӯб бештар бозӣ кун — ин хушоянд ва барои саломатӣ муфид аст.",
