    kazgenre_explain: "بارىس قازاق تىلىدىكى ھەرخىل ژانردىكى مەتىنلەرنى پەرقلەندۈرۈشنى ئۆگىنىۋاتىدۇ! شېئىر، چۆچەك ۋە تېپىشماقنىڭ — ھەر بىرىنىڭ ئۆز ئالاھىدىلىكى بار. چۈشەندۈرۈشنى ئوقۇڭ ۋە بۇ ژانر قازاقچە قانداق ئاتىلىدىغانلىقىنى تېپىڭ. تەييارمۇسىز؟",
