    moves_label: "قەدەم:",
    explain_heading: "بىز نېمە قىلىمىز؟",
    speak_button: "🔊 ئوقۇپ بېرىش",
    count_explain: "بارىس سىزنى سانلار دۇنياسىغا سەپەرگە تەكلىپ قىلىدۇ! 🔢 رەسىمدە خىلمۇخىل نەرسىلەر بار — ئۇلارنى رەت بويىچە سانا: بىر، ئىككى، ئۈچ… خاتالاشما! ساناپ بولغاندىن كېيىن سېلىشتۇرۇڭ: قايسى سان چوڭ، قايسىسى كىچىك. قانچىلىك دىققەت بىلەن سانىسىڭىز، شۇنچىلىك كۆپ يۇلتۇز ئالىسىز. سەپەرگە تەييارمۇسىز؟",
    addition_explain: "بارىسنىڭ بىر سىرى بار: قوشۇش — ئىككى گۇرۇپپا نەرسىنى بىر گۇرۇپپىغا بىرلەشتۈرۈش! بىر قولۇڭدا ئالما، يەنە بىر قولۇڭدىمۇ ئالما بولسا — ئۇلارنى قوشۇپ، جەمئىي قانچە بولغانلىقىنى سانا. ھەر ئىككى گۇرۇپپىغا دىققەت بىلەن قارا ۋە كۆرگىنىڭنىڭ ھەممىسىنى قوشۇشنى ئۇنتۇما. سانلارنى قوشۇشقا تەييارمۇسىز؟",
    subtract_explain: "ئەمدى بارىس سىزگە ئەكسىچە بىر ترۈك كۆرسىتىدۇ! ئېزىش — نەرسىلەرنىڭ بىر قىسمى كېتىپ، قالغىنىنى ساناشقا ئوخشايدۇ. قوشۇش بىلەن ئېزىش ئەكسىچە دوستلارغا ئوخشايدۇ: بىرى بىرلەشتۈرىدۇ، يەنە بىرى ئېلىپ تاشلايدۇ. قانچە نەرسە يوقالغانلىقىنى كۆر ۋە قالغىنىنى سانا. سىناپ كۆرۈشكە تەييارمۇسىز؟",
    compare_explain: "بارىس «كۆپ ياكى ئاز» ئويۇنىنى ياخشى كۆرىدۇ! ئىككى ساننى سېلىشتۇرۇش ئۈچۈن، ھەر گۇرۇپپىدا قانچە نەرسە بارلىقىنى سانا، ئاندىن قارا — قايسىسىدا كۆپ، قايسىسىدا ئاز. ئۇلار ھەتتا باراۋەرمۇ بولۇشى مۇمكىن! سېلىشتۇرۇشتىن بۇرۇن ھەر گۇرۇپپىنى دىققەت بىلەن سانا. سانلارنى سېلىشتۇرۇشقا تەييارمۇسىز؟",
    letter_explain: "بارىس سىزگە بىر سىرنى پىچىرلايدۇ: ھەر بىر ھەرپنىڭ ئۆز ئاۋازى بار! ئېكراندىكى چوڭ ھەرپكە قاراڭ — ئەمدى شۇ ئاۋازدىن باشلىنىدىغان ناملىق رەسىمنى تېپىڭ. ھەر سۆزنىڭ بىرىنچى ھەرپى قانداق ئاڭلىنىدىغانلىقىنى ئاڭلاڭ ۋە بارىس كۆرسەتكەن ھەرپ بىلەن سېلىشتۇرۇڭ. ھەرپلەرنى ئىزدەشكە تەييارمۇسىز؟",
    word_explain: "بارىس سىزگە تارقاق ھەرپلەرنى تەييارلىدى! ھەر سۆز بىر-بىرىنىڭ ئارقىسىدىن رەت بويىچە تۇرىدىغان ھەرپلەردىن تەشكىل تاپىدۇ. رەسىمگە قاراڭ — ئۇ قايسى سۆزنى تۈزۈش كېرەكلىكىنى ئېيتىدۇ. تولۇق سۆز چىققۇچە ھەرپلەرنى بىردىن بېسىڭ. سۆز تۈزۈشكە تەييارمۇسىز؟",
    vowel_explain: "بارىس ئاۋازلارنىڭ سىرىنى ئاچىدۇ! سوزۇق ئاۋازلار ئەركىن ئېيتىلىدۇ، ئاغزىڭىزغا ھېچنېمە توسقۇنلۇق قىلمايدۇ — ئا-ئا-ئا، ئو-ئو-ئو! ئۈزۈك ئاۋازلار بولسا توسالغۇ بىلەن ئېيتىلىدۇ — لەۋ، چىش ياكى تىل بىلەن، مەسىلەن ب ياكى س. ھەرپنى ئاڭلاڭ ۋە ئويلاڭ: بۇ سوزۇقمۇ ياكى ئۈزۈكمۇ؟ ئاۋازلارنى ھەل قىلىشقا تەييارمۇسىز؟",
    syllable_explain: "بارىس سۆزلەرنى چاۋاك چېلىپ بۆلۈشنى بىلىدۇ! ھەر سۆزنى كىچىك بۆلەكلەرگە — بوغۇملارغا بۆلگىلى بولىدۇ. سۆزنى قولۇڭىز بىلەن چاۋاك چېلىپ كۆرۈڭ: قانچە قېتىم چاۋاك چالسىڭىز، شۇنچە بوغۇم بار! ئېكراندىكى سۆزگە قاراڭ ۋە ئۇنىڭدا قانچە بوغۇم بارلىقىنى سانا. سۆزلەرنى چاۋاك چېلىشقا تەييارمۇسىز؟",
    hub_shapes_title: "سىزىقنى تېپىڭ",
    hub_shapes_desc: "چېكىت، تۈز سىزىق، كېسىندى، بۇلۇڭ...",
    hub_lecture_shapes_title: "دەرس: سىزىقلار ۋە شەكىللەر",
    hub_lecture_shapes_desc: "چېكىت، تۈز سىزىق، كېسىندى، بۇلۇڭ تەپسىلىي",
    lecture_shapes_title: "دەرس: سىزىقلار ۋە شەكىللەر",
    lecture_shapes_sub: "سىزىقلار ۋە ئاددىي شەكىللەرنى پەرقلەندۈرۈشنى ئۆگىنىڭ",
    shapes_s1_title: "سىزىقلار ۋە شەكىللەر",
    shapes_s1_text: "بارىس ھەقىقىي گېئومېتر! بۈگۈن ھەر خىل سىزىقلار ۋە ئاددىي شەكىللەرنىڭ قانداق ئاتىلىدىغانلىقىنى بىلىمىز. سىزىقلارنى ئۆگىنىشكە تەييارمۇسىز؟",
    shapes_s2_title: "چېكىت ۋە تۈز سىزىق",
    shapes_s2_text: "چېكىت — قەغەزدىكى كىچىك بىر چېكىت خالاس. تۈز سىزىق تۈز مېڭىدۇ، ئەگرى بولمايدۇ، ئۇنىڭ باشلىنىشى ھەم ئاخىرى يوق — ئۇ ئىككى تەرەپكە چەكسىز داۋام قىلىدۇ.",
    shapes_s3_title: "ئەگرى ۋە سۇنۇق سىزىق",
    shapes_s3_text: "ئەگرى سىزىق بۇرۇلۇشلىرى بار يول سىڭارى يۇمشاق ئەگىلىدۇ. سۇنۇق سىزىق بولسا چاقماقتەك ئۆتكۈر بۇلۇڭلار بىلەن ئۇ يەردىن-بۇ يەرگە سەكرەيدۇ!",
    shapes_s4_title: "كېسىندى ۋە نۇر",
    shapes_s4_text: "كېسىندى — تۈز سىزىقنىڭ باشلىنىشى ۋە ئاخىرى بار قىسمى. نۇر مۇ تۈز سىزىقنىڭ قىسمى، بىراق ئۇنىڭ پەقەت باشلىنىشى بار، ئاخىرى يوق — ئۇ بىر تەرەپكە چەكسىز داۋام قىلىدۇ.",
    shapes_s5_title: "بۇلۇڭ",
    shapes_s5_text: "ئىككى نۇر بىر چېكىتتىن چىققاندا بۇلۇڭ ھاسىل بولىدۇ. بۇ چېكىت بۇلۇڭنىڭ چوققىسى دەپ ئاتىلىدۇ.",
    shapes_s6_title: "سىز سىزىقلار ۋە شەكىللەرنى بىلىسىز!",
    shapes_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز چېكىت، تۈز سىزىق، ئەگرى، سۇنۇق سىزىق، كېسىندى، نۇر ۋە بۇلۇڭنى پەرقلەندۈرەلەيسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    shapes_game_title: "سىزىقنى تېپىڭ!",
    shapes_game_sub: "بۇ سىزىق ياكى شەكىل قانداق ئاتىلىدۇ؟ ماس رەسىمنى تېپىڭ",
    shapes_explain: "بارىس ھەقىقىي گېئومېتر! سىزىقلارنىڭ ھەر خىل ئاتلىرى بار: چېكىت — بۇ كىچىك بىر چېكىت، تۈز سىزىق ئىككى تەرەپكىمۇ تۈز، چەكسىز داۋاملىشىدۇ، ئەمما سۇنۇق سىزىق چاقماقتەك ئۇ يەردىن-بۇ يەرگە سەكرەيدۇ! ئاتىغا قاراپ، ماس سىزىقنى تېپىڭ. سىزىقلارنى ئۆگىنىشكە تەييارمۇسىز؟",
