    flatsolid_s2_title: "تەكشى شەكىللەر",
    flatsolid_s2_text: "تەكشى شەكىللەر قەغەزدىكى رەسىمگە ئوخشايدۇ — ئۇلارنىڭ قېلىنلىقى يوق. مەسىلەن، چەمبەر ياكى كۋادراتنى بىر پارچە قەغەزگە سىزغىلى بولىدۇ.",
    flatsolid_s3_title: "ھەجىملىك شەكىللەر",
    flatsolid_s3_text: "ھەجىملىك شەكىللەر قولىڭىزغا ئېلىپ ئايلاندۇرغىلى بولىدىغان نەرسىلەر، ئۇلارنىڭ قېلىنلىقى ۋە ھەجىمى بار. مەسىلەن، توپ (شار) ياكى كۇب.",
    flatsolid_s4_title: "توپ بىلەن چەمبەر ئوخشاش ئەمەس",
    flatsolid_s4_text: "چەمبەر — تەكشى، ئۇنى سىزغىلى بولىدۇ. توپ بولسا — ھەجىملىك، ھەممە تەرەپتىن يۇمىلاق، ئۇنى دومىلاتقىلى بولىدۇ.",
