    flatsolid_s6_title: "سىز شەكىللەرنى پەرقلەندۈرەلەيسىز!",
    flatsolid_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز تەكشى شەكىللەرنى ھەجىملىك شەكىللەردىن پەرقلەندۈرەلەيسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    flatsolid_game_title: "تەكشىمۇ ياكى ھەجىملىكمۇ؟",
