    flatsolid_explain: "بارىس ھەر خىل نەرسىلەرنى كۆرسىتىدۇ! تەكشى شەكىللەر قەغەزدىكى رەسىمگە ئوخشاش، قېلىنلىقى يوق، مەسىلەن چەمبەر ياكى تۆت چاسا. ھەجىملىك شەكىللەر بولسا ھەجىمگە ئىگە، قولىڭىزدا ئايلاندۇرغىلى بولىدۇ، مەسىلەن توپ (شار) ياكى كۇب. نەرسىگە قاراپ ئويلاڭ: ئۇ تەكشىمۇ ياكى ھەجىملىكمۇ؟ چۈشىنىشكە تەييارمۇسىز؟",
