    riddle_game_sub: "تېپىشماقنى ئوقۇپ جاۋابىنى تاللاڭ",
    riddle_explain: "بارىس تېپىشماقلارنى ياخشى كۆرىدۇ! ھەر تېپىشماقتا بىر نەرسە يوشۇرۇنغان — بەلگىلەرنى دىققەت بىلەن ئوقۇپ، ئۇنىڭ نېمە ئىكەنلىكىنى تېپىش كېرەك. تېپىشماقنى ئوقۇپ توغرا رەسىمنى تاللاڭ. تېپىشقا تەييارمۇسىز؟",
    hub_story_title: "ھېكايىنى تۈزۈڭ",
    hub_story_desc: "رەسىملەرنى تەرتىپ بىلەن قويۇڭ",
    story_game_title: "ھېكايىنى تۈزۈڭ!",
    story_game_sub: "رەسىملەرنى توغرا تەرتىپتە بېسىڭ",
    story_explain: "بارىس سۆزسىز، پەقەت رەسىملەر بىلەن ھېكايە ئېيتىدۇ! تۆۋەندىكى بارلىق رەسىملەرگە قاراڭ ۋە ئالدى بىلەن نېمە بولغانلىقىنى، ئاندىن نېمە بولغانلىقىنى ئويلاڭ. توغرا ھېكايە چىقىشى ئۈچۈن رەسىملەرنى تەرتىپ بىلەن بېسىڭ. ھېكايە تۈزۈشكە تەييارمۇسىز؟",
