    hub_alippe_letters2_title: "ھەرپنى تېپىڭ (2-گۇرۇپپا)",
    hub_alippe_letters2_desc: "с, о, т, қ, ы, м, е, д, ш, ұ",
    alippe_letters2_explain: "بارىس ئېلىپبەنى داۋاملىق ئۆگىنىۋاتىدۇ! بىرىنچى گۇرۇپپىدىن كېيىن بۇ ئاۋازلار كېلىدۇ: с، о، т، қ، ы، м، е، д، ш، ұ. رەسىمگە قاراڭ ۋە ئۇنىڭ ئاتى قايسى ھەرپتىن باشلىنىدىغانلىقىنى تېپىڭ. داۋاملاشتۇرۇشقا تەييارمۇسىز؟",
    hub_prebukvar_title: "ئاۋاز، بوغۇم، سۆز، جۈملە",
