    alippe_letters1_explain: "بارىس قازاق ئېلىپبەسىنى (Әліппе) ئۆگىنىۋاتىدۇ! ئەخمەت بايتۇرسىنوف ئۇسۇلى بويىچە، ئالدى بىلەن ئەڭ كۆپ ئۇچرايدىغان ئاۋازلار ئۆگىتىلىدۇ: а، р، л، н. رەسىمگە قاراڭ ۋە ئۇنىڭ ئاتى قايسى ھەرپتىن باشلىنىدىغانلىقىنى تېپىڭ. ئېلىپبەنى ئۆگىنىشكە تەييارمۇسىز؟",
