    hub_vowelharmony_title: "قاتتىقمۇ، يۇمشاقمۇ؟",
    hub_vowelharmony_desc: "سوزۇق تاۋۇشلار",
    vowelharmony_explain: "بارىس قازاق تىلىدىكى سوزۇقلارنىڭ قاتتىق ۋە يۇمشاق بولىدىغانلىقىنى ئۆگىنىۋاتىدۇ! قاتتىق سوزۇقلار: а، о، ұ، ы. يۇمشاق سوزۇقلار: ә، е، ө، ү، і. ھەرپكە قاراڭ ۋە ئۇ قاتتىقمۇ، يۇمشاقمۇ تېپىڭ. تەييارمۇسىز؟",
    vowelharmony_game_title: "قاتتىقمۇ، يۇمشاقمۇ؟",
