    anatili_q3_note: "بۇ چارەكنىڭ قالغان تېمىلىرى ھەقىقىي ئېغىزچە نۇتۇق ۋە قول بىلەن يېزىشنى تەلەپ قىلىدۇ — توپچا ئويۇنلىرىغا ئايلاندۇرغىلى بولمايدۇ",
    hub_capital_title: "چوڭ ھەرپمۇ؟",
    hub_capital_desc: "ئىسىملار ۋە ئادەتتىكى سۆزلەر",
    capital_explain: "بارىس قايسى سۆزلەر چوڭ ھەرپ بىلەن يېزىلىدىغانلىقىنى ئۆگىنىۋاتىدۇ! ئادەم ئىسمى (ئايگۈل)، شەھەر نامى (ئالماتى) ۋە ھايۋان لەقىمى (ئاقبار) — چوڭ ھەرپ بىلەن. ئادەتتىكى سۆزلەر (қала، ит) — كىچىك ھەرپ بىلەن. سۆزنى ئوقۇڭ ۋە توغرا جاۋابنى تېپىڭ. تەييارمۇسىز؟",
    capital_game_title: "چوڭ ھەرپمۇ؟",
