    hub_wordharmony_title: "سۆز قاتتىقمۇ، يۇمشاقمۇ؟",
    hub_wordharmony_desc: "سوزۇق تاۋۇشلار قانۇنى",
    wordharmony_explain: "بارىس سىڭگارمونىزم قانۇنىنى ئۆگىنىۋاتىدۇ! قازاقچە سۆزدە بارلىق سوزۇقلار ياكى ھەممىسى قاتتىق، ياكى ھەممىسى يۇمشاق بولىدۇ. سۆزگە قاراڭ ۋە ئۇ قاتتىق سۆزمۇ، يۇمشاق سۆزمۇ تېپىڭ. تەييارمۇسىز؟",
