    lecture_kazakh_video_title: "ۋىدېئو دەرس: سالەم!",
    lecture_kazakh_explain: "بارىس سىزنى قازاق تىلى بويىچە ۋىدېئو دەرسكە تەكلىپ قىلىدۇ! ئوقۇتقۇچى قازاقچە قانداق سالام بېرىش ۋە ئىسمىنى سوراشنى كۆرسىتىدۇ — «سالەم! سېنىڭ ئاتىڭ كىم؟». سىز بىزنىڭ قازاقچە سۆزلەر ھەققىدىكى ئويۇنلىرىمىزنى ئوينىدىڭىز، ئەمدى ھەقىقىي قازاقچە سۆزلەشنى ئاڭلايسىز. كۆرۈشكە تەييارمۇسىز؟",
    hub_lecture_estestvo_title: "ۋىدېئو دەرس: ئۆسۈملۈك قىسىملىرى",
    hub_lecture_estestvo_desc: "ئۆسۈملۈكلەرنى تەپسىلىي",
    lecture_estestvo_video_title: "ۋىدېئو دەرس: ئۆسۈملۈك قىسىملىرى!",
    lecture_estestvo_explain: "بارىس سىزنى تەبىئىي پەن بويىچە ۋىدېئو دەرسكە تەكلىپ قىلىدۇ! سىز ئۆسۈملۈك قىسىملىرى ھەققىدىكى ئويۇنىمىزنى ئوينىدىڭىز — ئەمدى ئوقۇتقۇچى يىلتىز، پوپا، يوپۇرماق، گۈل ۋە مېۋە ھەققىدە تەپسىلىي سۆزلەيدىغان ھەقىقىي ۋىدېئو دەرسنى كۆرۈڭ. كۆرۈشكە تەييارمۇسىز؟",
    hub_lecture_digital_title: "ۋىدېئو دەرس: ئۈسكۈنىلەر",
    hub_lecture_digital_desc: "كومپيۇتېرنى تەپسىلىي",
    lecture_digital_video_title: "ۋىدېئو دەرس: ئۈسكۈنىلەر!",
    lecture_digital_explain: "بارىس سىزنى رەقەملىك سەۋاتلىق بويىچە ۋىدېئو دەرسكە تەكلىپ قىلىدۇ! سىز كومپيۇتېر ئۈسكۈنىلىرى ھەققىدىكى ئويۇنىمىزنى ئوينىدىڭىز — ئەمدى كومپيۇتېرنىڭ نېمە ئىكەنلىكى ۋە ئۇنىڭ ھەر خىل قىسىملىرىنىڭ نېمە ئۈچۈن كېرەكلىكىنى تەپسىلىي چۈشەندۈرىدىغان مۇلتفىلىمنى كۆرۈڭ. كۆرۈشكە تەييارمۇسىز؟",
    hub_lecture_poznanie_title: "ۋىدېئو دەرس: سىۋىتوفور",
    hub_lecture_poznanie_desc: "يول ھەرىكىتى قائىدىلىرىنى تەپسىلىي",
    lecture_poznanie_video_title: "ۋىدېئو دەرس: سىۋىتوفور!",
    lecture_poznanie_explain: "بارىس سىزنى دۇنيانى تونۇش بويىچە ۋىدېئو دەرسكە تەكلىپ قىلىدۇ! سىز يول بەلگىلىرى ھەققىدىكى ئويۇنىمىزنى ئوينىدىڭىز — ئەمدى سىۋىتوفور ۋە يول ھەرىكىتى قائىدىلىرى ھەققىدە تەپسىلىي سۆزلەيدىغان مۇلتفىلىمنى كۆرۈڭ. كوچىدا بىخەتەر بولۇش ئۈچۈن بۇنى بىلىش ناھايىتى مۇھىم. كۆرۈشكە تەييارمۇسىز؟",
    hub_lecture_muzyka_title: "ۋىدېئو دەرس: ئەسۋاپلار",
