    lecture_muzyka_explain: "بارىس سىزنى مۇزىكا بويىچە ۋىدېئو دەرسكە تەكلىپ قىلىدۇ! سىز مۇزىكا ئەسۋابلىرى ھەققىدىكى ئويۇنىمىزنى ئوينىدىڭىز — ئەمدى ھەر خىل ئەسۋابلارنىڭ قانداق ئاۋاز چىقىرىدىغانلىقىنى كۆرسىتىدىغان مۇلتفىلىمنى كۆرۈڭ. كۆرۈشكە تەييارمۇسىز؟",
