    plantparts_explain: "بارىس ئۆسۈملۈكلەرنى ئۆگىنىۋاتىدۇ! ھەر ئۆسۈملۈكنىڭ ھەر خىل قىسىملىرى بار: يىلتىز ئۇنى توپىدا تۇتۇپ تۇرىدۇ ۋە سۇ ئىچىدۇ، پوپا ئۆسۈملۈكنى تىرەيدۇ، يوپۇرماقلار قۇياش نۇرىنى تۇتىدۇ، گۈل بولسا ئىچىدە ئۇرۇقى بار مېۋىگە ئايلىنىدۇ. قىسىم ئاتىغا قاراپ ماس رەسىمنى تېپىڭ. ئۆسۈملۈكلەرنى ئۆگىنىشكە تەييارمۇسىز؟",
