    orderops_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز تىرناقنىڭ ئالدى بىلەن ھېسابلىنىدىغانلىقىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    units_explain: "بارىس سىزنى ئۇزۇنلۇق ئۆلچەم بىرلىكلىرىنى ئايلاندۇرۇشقا تەكلىپ قىلىدۇ! 1 مېتر — بۇ 10 دېتسىمېتر، 1 دېتسىمېتر — بۇ 10 سانتىمېتر. قىممەتنى كېرەكلىك بىرلىككە ئايلاندۇرۇڭ. تەييارمۇسىز؟",
