    roman_explain: "بارىس سىزنى رىم رەقەملىرى بىلەن تونۇشتۇرىدۇ! بۇرۇن سانلارنى بىز ئۆگەنگەندەك ئەمەس، باشقىچە يازاتتى — مەسىلەن، 5 سانى — V، 10 سانى — X. توغرا جاۋابنى تاللاڭ. تەييارمۇسىز؟",
