    setslogic_s1_text: "بارىس سىزنىڭ سانلارنى قانچىلىك ياخشى بىلىدىغانلىقىڭىزنى تەكشۈرىدۇ! بۈگۈن ئۈچ مۇھىم نەرسىنى كۆرۈپ ئۆتىمىز: سان 2 گە بۆلۈنەمدۇ، ئۇنىڭدا قانچە خانە بار، ۋە سانلارنى قانداق سېلىشتۇرۇش كېرەك. تەييارمۇسىز؟",
