    setslogic_s4_text: "سانلارنى سېلىشتۇرۇش ئۈچۈن ئالدى بىلەن قانچە خانىدىن تۇرىدىغانلىقىغا قاراڭ: خانىسى كۆپ سان چوڭراق. ئەگەر خانە سانى باراۋەر بولسا — سولدىن ئوڭغا، خانىمۇ-خانە سېلىشتۇرۇڭ.",
