    multiply_explain: "بارىس سىزگە كۆپەيتىش جەدۋىلىنى ئۆگىتىدۇ! كۆپەيتىش — ئوخشاش قوشۇلغۇچىلارنى قوشۇش. مەسىلەن، 3×4 — بۇ 4+4+4 بىلەن ئوخشاش. كۆپەيتىش مىساللىرىنى ھەل قىلىڭ ۋە جاۋابنى تاللاڭ. تەييارمۇسىز؟",
