    multiply_s1_title: "كۆپەيتىش",
    multiply_s1_text: "بارىس سىزگە كۆپەيتىشنى ئۆگىتىدۇ! كۆپەيتىش — ئوخشاش ساننى بىر قانچە قېتىم تېز قوشۇشنىڭ ئۇسۇلى. سىرىنى بىلىشكە تەييارمۇسىز؟",
    multiply_s2_title: "كۆپەيتىش — قوشۇش",
    multiply_s2_text: "3 × 4 دېگەن سۆز: 4 سانىنى ئېلىپ، ئۇنى 3 قېتىم قوشۇش. 3 × 4 = 4 + 4 + 4 = 12.",
    multiply_s3_title: "2 گە كۆپەيتىش جەدۋىلى",
    multiply_s3_text: "2 گە كۆپەيتىش — ساننى ئىككى ھەسسە ئاشۇرۇش. 2 × 3 = 6، 2 × 4 = 8، 2 × 5 = 10.",
    multiply_s4_title: "3 كە كۆپەيتىش",
    multiply_s4_text: "3 × 3 = 9، چۈنكى 3 + 3 + 3 = 9. 3 × 4 = 12، چۈنكى 3 + 3 + 3 + 3 = 12.",
