    multiply_s5_text: "كۆپەيتكۈچلەرنىڭ ئورنىنى ئالماشتۇرسىڭىز، كۆپەيتىندى ئۆزگەرمەيدۇ! 2 × 5 بىلەن 5 × 2 — بۇ ئوخشاش: ئىككىلىسىدىمۇ 10 چىقىدۇ.",
    multiply_s6_title: "سىز كۆپەيتەلەيسىز!",
    multiply_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز كۆپەيتىشنىڭ قانداق ئىشلەيدىغانلىقىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    divide_explain: "بارىس سىزگە سانلارنى بۆلۈشنى ئۆگىتىدۇ! بۆلۈش — تەڭ قىسىملارغا بۆلۈش، كۆپەيتىشكە قارىمۇ-قارشى ئەمەل. بۆلۈش مىساللىرىنى ھەل قىلىڭ ۋە جاۋابنى تاللاڭ. تەييارمۇسىز؟",
    divide_game_title: "بۆلۈش",
    divide_game_sub: "بۆلۈش مىسالىنى ھەل قىلىڭ",
    hub_divide_title: "بۆلۈش",
