    divide_s1_text: "بارىس سىزگە بۆلۈشنى ئۆگىتىدۇ! بۆلۈش — تەڭ قىسىملارغا ئايرىش. بۇنىڭ قانداق ئىشلەيدىغانلىقىنى بىلىشكە تەييارمۇسىز؟",
