    divide_s3_title: "تەڭ قىسىملار",
    divide_s3_text: "12 ÷ 4 دېگەن سۆز: 12 نەرسىنى 4 گۇرۇپپىغا تەڭ بۆل. ھەر گۇرۇپپىدا 3 تىن بولىدۇ.",
