    divide_s5_title: "كۆپەيتىش جەدۋىلىنى ئىشلىتىڭ",
    divide_s5_text: "بۆلۈش ئۈچۈن كۆپەيتىشنى ئېسىڭىزگە كەلتۈرۈڭ! ئەگەر 15 ÷ 3 نىڭ قانچە ئىكەنلىكىنى بىلمىسىڭىز، ئېسىڭىزگە كەلتۈرۈڭ: 3 × 5 = 15، دېمەك، 15 ÷ 3 = 5.",
    divide_s6_title: "سىز بۆلەلەيسىز!",
    divide_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز بۆلۈشنىڭ قانداق ئىشلەيدىغانلىقىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    angletype_explain: "بارىس سىزگە بۇلۇڭ تۈرلىرىنى پەرقلەندۈرۈشنى ئۆگىتىدۇ! ئۆتكۈر بۇلۇڭ — كىچىك ۋە تار، توغرا بۇلۇڭ — قەغەز بەتنىڭ بۇلۇڭىغا ئوخشايدۇ، تومپاق بۇلۇڭ — كەڭ، توغرىدىن چوڭ. بۇلۇڭغا قاراپ، ئۇنىڭ تۈرىنى تاللاڭ. تەييارمۇسىز؟",
