    turn_quarter_cw: "سائەت يۆنىلىشى بويىچە چارەك بۇرۇلۇش",
    turn_quarter_ccw: "سائەتكە قارىمۇ-قارشى چارەك بۇرۇلۇش",
    turn_half: "يېرىم بۇرۇلۇش",
    turn_full: "تولۇق بۇرۇلۇش",
    hub_lecture_turns_title: "دەرس: بۇرۇلۇشلار",
    hub_lecture_turns_desc: "يۆنىلىش ۋە ھەرىكەت تەپسىلىي",
    lecture_turns_title: "دەرس: بۇرۇلۇشلار",
    lecture_turns_sub: "بۇرۇلغاندىن كېيىنكى يۆنىلىشنى بەلگىلەشنى ئۆگىنىڭ",
    turns_s1_title: "بۇرۇلۇشلار",
    turns_s1_text: "بارىس سىزگە بۇرۇلۇشلار ھەققىدە ئۆگىتىدۇ! يا چارەك بۇرۇلۇش، يېرىم بۇرۇلۇش ياكى تولۇق بۇرۇلۇش قىلالايدۇ — سائەت يۆنىلىشى بويىچە ياكى ئۇنىڭغا قارىمۇ-قارشى. بىلىۋېلىشقا تەييارمۇسىز؟",
    turns_s2_title: "سائەت يۆنىلىشى بويىچە چارەك بۇرۇلۇش",
    turns_s2_text: "سائەت يۆنىلىشى بويىچە دېگەن سائەت تىللىرى ماڭىدىغان يۆنىلىش بىلەن ئوخشاش. ئەگەر يا ئۈستىگە قارىغان بولسا ۋە سائەت يۆنىلىشى بويىچە چارەك بۇرۇلسا — ئۇ ئوڭغا قارايدۇ.",
    turns_s3_title: "سائەتكە قارىمۇ-قارشى چارەك بۇرۇلۇش",
    turns_s3_text: "سائەتكە قارىمۇ-قارشى — بۇ ئەكسى يۆنىلىش. ئەگەر يا ئۈستىگە قارىغان بولسا ۋە سائەتكە قارىمۇ-قارشى چارەك بۇرۇلسا — ئۇ سولغا قارايدۇ.",
    turns_s4_title: "يېرىم بۇرۇلۇش",
    turns_s4_text: "يېرىم بۇرۇلۇش — بۇ 180° بۇرۇلۇش، سائەت يۆنىلىشى بويىچە بولسۇن، قارىمۇ-قارشى بولسۇن — نەتىجە ئوخشاش. ئەگەر يا ئۈستىگە قارىغان بولسا، يېرىم بۇرۇلغاندىن كېيىن ئۇ ئاستىغا قارايدۇ.",
    turns_s5_title: "تولۇق بۇرۇلۇش",
    turns_s5_text: "تولۇق بۇرۇلۇش — بۇ 360° بۇرۇلۇش. يا پۈتۈن چەمبەردىن ئۆتۈپ، دەسلەپكى قارىغان يۆنىلىشىگە قايتىدۇ!",
    turns_s6_title: "سىز بۇرۇلۇشلارنى بەلگىلىيەلەيسىز!",
    turns_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز بۇرۇلغاندىن كېيىن يانىڭ قەيەرگە قارايدىغانلىقىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    animalclass_explain: "بارىس سىزنى ھايۋانلار سىنىپلىرى بىلەن تونۇشتۇرىدۇ! ھاشارەتلەر، بېلىقلار، ئىككى مۇھىتلىقلار، سۆرۈلگۈچىلەر، قۇشلار ۋە سۈت ئېمىزگۈچىلەر بار. ھايۋانغا قاراپ، ئۇ قايسى سىنىپقا تەۋەلىكىنى تاللاڭ. تەييارمۇسىز؟",
    animalclass_game_title: "ھايۋانلار سىنىپلىرى",
    animalclass_game_sub: "ھايۋاننىڭ سىنپىنى بەلگىلەڭ",
    hub_animalclass_title: "ھايۋانلار سىنىپلىرى",
    hub_animalclass_desc: "ھاشارەتلەر، بېلىقلار، قۇشلار ۋە باشقىلار",
    animalclass_insect: "ھاشارەتلەر",
    animalclass_fish: "بېلىقلار",
    animalclass_amphibian: "ئىككى مۇھىتلىقلار",
    animalclass_reptile: "سۆرۈلگۈچىلەر",
