    lecture_animalclass_sub: "ھەر بىر ھايۋانلار گۇرۇپپىسى ھەققىدە تەپسىلىي بىلىڭ",
    animalclass_s1_title: "ھايۋانلار دۇنياسى",
    animalclass_s1_text: "بارىس سىزنى ئاجايىپ بىر سەپەرگە تەكلىپ قىلىدۇ! يەر يۈزىدىكى بارلىق ھايۋانلار چوڭ گۇرۇپپىلارغا بۆلۈنىدۇ — ئۇلار سىنىپ دەپ ئاتىلىدۇ. بۈگۈن ئالتە سىنىپ ھەققىدە بىلىمىز: ھاشارەتلەر، بېلىقلار، ئىككى مۇھىتلىقلار، سۆرۈلگۈچىلەر، قۇشلار ۋە سۈت ئېمىزگۈچىلەر. تەييارمۇسىز؟",
    animalclass_s2_title: "ھاشارەتلەر",
    animalclass_s2_text: "ھاشارەتلەرنىڭ ئالتە پۇتى بار — ئۈچ جۈپ. كېپىنەكلەر، چۆمۈلىلەر، قوڭغۇزلار، ھەرىلەر ۋە ئىنەلىكلەر بۇ گۇرۇپپىغا كىرىدۇ. يەر يۈزىدە ھاشارەتلەر باشقا بارلىق ھايۋانلاردىن كۆپ!",
    animalclass_s3_title: "بېلىقلار",
    animalclass_s3_text: "بېلىقلار سۇدا — دەريا، كۆل ۋە دېڭىزلاردا ياشايدۇ. تېنى تاشچىلار بىلەن قاپلانغان بولۇپ، ئۇلار بىزدەك ئۆپكە بىلەن ئەمەس، سۇ ئاستىدا نەپەس ئالالايدۇ.",
    animalclass_s4_title: "ئىككى مۇھىتلىقلار",
    animalclass_s4_text: "ئىككى مۇھىتلىقلار سۇدىمۇ، قۇرۇقلۇقتىمۇ ياشىيالايدۇ. ئەڭ مەشھۇر مىسالى — پاقا: كىچىك چېغىدا سۇدا ئۈزىدۇ، چوڭ بولغاندا قۇرۇقلۇقتا سەكرەيدۇ.",
    animalclass_s5_title: "سۆرۈلگۈچىلەر",
    animalclass_s5_text: "سۆرۈلگۈچىلەرنىڭ تېرىسى قۇرۇق بولۇپ، تاشچىلار ياكى قاتتىق قاپاق بىلەن قاپلانغان. يىلان، كەسلەنچۈك، تاشپاقا ۋە تىمساھ بۇ گۇرۇپپىغا كىرىدۇ.",
    animalclass_s6_title: "قۇشلار",
    animalclass_s6_text: "قۇشلارنىڭ تېنى يۇڭ ياكى تاشچا بىلەن ئەمەس، پەير بىلەن قاپلانغان. قۇشلارنىڭ ھەممىسى دېگۈدەك ئۇچالايدۇ ھەمدە ھەممىسى تۇخۇمدىن چىقىدۇ.",
    animalclass_s7_title: "سۈت ئېمىزگۈچىلەر",
    animalclass_s7_text: "سۈت ئېمىزگۈچىلەرنىڭ تېنى يۇڭ بىلەن قاپلانغان. ئۇلار بالىلىرىنى سۈت بىلەن ئوزۇقلاندۇرىدۇ — مۈشۈكمۇ، ئىتمۇ، پىلمۇ، ھەتتا كىتمۇ شۇنداق قىلىدۇ. ئىنسانمۇ سۈت ئېمىزگۈچىلەرگە كىرىدۇ!",
    animalclass_s8_title: "سىز ھايۋانلار بويىچە ئۇستا بولدىڭىز!",
    animalclass_s8_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز ھايۋانلارنىڭ ئالتە سىنپىنىمۇ بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    plantfunc_explain: "بارىس سىزگە ئۆسۈملۈكنىڭ ھەر بىر قىسمى نېمىشقا كېرەكلىكىنى ئېيتىپ بېرىدۇ! يىلتىز، ساپاق، يوپۇرماق ۋە گۈلنىڭ ھەر بىرىنىڭ ئۆز مۇھىم رولى بار. ئۆسۈملۈك قىسمىغا قاراپ، ئۇنىڭ نېمە قىلىدىغانلىقىنى تاللاڭ. تەييارمۇسىز؟",
