    lecture_plantfunc_sub: "ئۆسۈملۈككە ھەر قىسىمنىڭ نېمە ئۈچۈن كېرەك ئىكەنلىكىنى بىلىڭ",
    plantfunc_s1_title: "ئۆسۈملۈكنىڭ قۇرۇلمىسى",
    plantfunc_s1_text: "بارىس سىزنى ئۆسۈملۈكنى ئىچىدىن تونۇشقا تەكلىپ قىلىدۇ! ھەر بىر ئۆسۈملۈكنىڭ تۆت ئاساسلىق قىسمى بار — يىلتىز، ساپاق، يوپۇرماق ۋە گۈل. ھەر قىسىمنىڭ ئۆز مۇھىم ۋەزىپىسى بار. قايسى ئىكەنلىكىنى بىلىشكە تەييارمۇسىز؟",
    plantfunc_s2_title: "يىلتىز",
    plantfunc_s2_text: "يىلتىز تۇپراق ئاستىدا يوشۇرۇنغان. ئۇ تۇپراقتىن سۇ ۋە ئوزۇق ماددىلارنى سىڭدۈرۈپ، پۈتۈن ئۆسۈملۈككە يەتكۈزىدۇ. يىلتىزسىز ئۆسۈملۈك سۇ ئىچەلمەيتتى!",
    plantfunc_s3_title: "ساپاق",
    plantfunc_s3_text: "ساپاق يىلتىزنى ئۆسۈملۈكنىڭ قالغان قىسىمى بىلەن باغلايدىغان تۇرۇبىغا ئوخشايدۇ. سۇ ۋە پايدىلىق ماددىلار ئۇ ئارقىلىق يىلتىزدىن يوپۇرماققا يەتكۈزۈلىدۇ.",
    plantfunc_s4_title: "يوپۇرماق",
    plantfunc_s4_text: "يوپۇرماقلار قۇياش نۇرىنى توپلايدۇ — بۇ ئۆسۈملۈككە ئۆزىگە ئوزۇق تەييارلاش ئۈچۈن كېرەك. يوپۇرماق قانچە كۆپ نۇر توپلىسا، ئۆسۈملۈك شۇنچە ياخشى ئۆسىدۇ.",
    plantfunc_s5_title: "گۈل",
    plantfunc_s5_text: "گۈل — ئۆسۈملۈكنىڭ ئەڭ چىرايلىق قىسمى. ئۇنىڭ ئاساسلىق ۋەزىپىسى — يېڭى ئۆسۈملۈكلەر ئۈنىدىغان ئۇرۇق بېرىش.",
    plantfunc_s6_title: "سىز ئۆسۈملۈكنى ئىچىدىن بىلىسىز!",
    plantfunc_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز يىلتىز، ساپاق، يوپۇرماق ۋە گۈلنىڭ نېمە ئۈچۈن كېرەك ئىكەنلىكىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    seasonplant_explain: "بارىس سىزگە ھەر خىل پەسىلدە ئۆسۈملۈكلەرگە نېمە بولىدىغانلىقىنى ئېيتىپ بېرىدۇ! باھار، ياز، كۈز ۋە قىشتا ئۆسۈملۈكلەر ھەرخىل كۆرۈنىدۇ. پەسىلگە قاراپ، ئۆسۈملۈكلەرگە نېمە بولىدىغانلىقىنى تاللاڭ. تەييارمۇسىز؟",
    seasonplant_game_title: "ئۆسۈملۈكلەرنىڭ پەسىللىك ئۆزگىرىشى",
