    seasonplant_s1_title: "پەسىللەر ۋە ئۆسۈملۈكلەر",
    seasonplant_s1_text: "بارىس سىزنى پۈتۈن يىل بويى ئۆسۈملۈكلەرنى كۆزىتىشكە تەكلىپ قىلىدۇ! ھەر پەسىلدە ئۆسۈملۈكلەر پۈتۈنلەي باشقىچە كۆرۈنىدۇ — ھازىر قانداق ئىكەنلىكىنى بىلىۋالايلى. تەييارمۇسىز؟",
    seasonplant_s2_title: "باھار",
