    seasonplant_s3_title: "ياز",
    seasonplant_s3_text: "يازدا ئۆسۈملۈكلەر ئەڭ تېز ئۆسىدۇ. ئۇلار گۈللەيدۇ، شىرەگە تولىدۇ ۋە مېۋە بېرىدۇ — تەبىئەت ئۈچۈن ئەڭ پائال پەسىل.",
    seasonplant_s4_title: "كۈز",
    seasonplant_s4_text: "كۈزدە يوپۇرماقلار رەڭگىنى ئۆزگەرتىدۇ — سېرىق، قىزغۇچ ۋە قىزىل بولىدۇ — ئاندىن چۈشۈپ كېتىدۇ. ئۆسۈملۈكلەر شۇنداق قىلىپ سوغۇق قىشقا تەييارلىنىدۇ.",
    seasonplant_s5_title: "قىش",
    seasonplant_s5_text: "قىشتا ئۆسۈملۈكلەر تىنچ ھالەتتە بولىدۇ: ئۆسۈش توختايدۇ، دەرەخلەر يوپۇرماقسىز تۇرۇپ باھارنى كۈتىدۇ.",
    seasonplant_s6_title: "سىز تۆتىلا پەسىلنى بىلىسىز!",
    seasonplant_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز باھار، ياز، كۈز ۋە قىشتا ئۆسۈملۈكلەرگە نېمە بولىدىغانلىقىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    waterprops_explain: "بارىس سىزگە سۇنىڭ خاسىيەتلىرى ھەققىدە سۆزلەپ بېرىدۇ! سۇنىڭ تەمى ۋە پۇرىقى يوق، ئۇ ئېقىپ، شەكلىنى ئۆزگەرتەلەيدۇ. گەپنى ئوقۇڭ ۋە توغرا ياكى خاتا ئىكەنلىكىنى ھەل قىلىڭ. تەييارمۇسىز؟",
