    waterprops_s1_title: "ئەتراپىمىزدىكى سۇ",
    waterprops_s1_text: "بارىس سىزنى سۇنىڭ سىرلىرىنى بىلىشكە تەكلىپ قىلىدۇ! سۇ ھەممە يەردە بار — دەريالاردا، كرانلاردا، چاينەكتە ھەتتا بۇلۇتلاردىمۇ. بۈگۈن سۇنىڭ ھەقىقىي قانداق ئىكەنلىكىنى بىلىۋالايلى. تەييارمۇسىز؟",
