    waterprops_s4_title: "مۇز، سۇ ۋە پار",
    waterprops_s4_text: "سۇ ھەر خىل ھالەتكە ئۆتەلەيدۇ. سوغۇقتا ئۇ مۇزلاپ، مۇزغا ئايلىنىدۇ. ئەگەر ئۇنى قاتتىق قىزىتسىڭىز — پارغا ئايلىنىدۇ.",
    waterprops_s5_title: "سۇنىڭ تەبىئىي مەنبەلىرى",
    waterprops_s5_text: "دەريا، كۆل ۋە دېڭىزلار سۇنىڭ تەبىئىي مەنبەلىرى. سۇ شۇ يەردىن بىزنىڭ ئۆيلىرىمىزگە كېلىپ، ئىچىش ۋە يۇيۇنۇشىمىزغا ياردەم بېرىدۇ.",
    waterprops_s6_title: "سىز سۇ ھەققىدە ھەممىنى بىلىسىز!",
    waterprops_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز سۇنىڭ ئاساسلىق خاسىيەتلىرىنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    bodyhealth_explain: "بارىس سىزگە ئىنسان تېنى ۋە دەنسائاتلىقى ھەققىدە سۆزلەپ بېرىدۇ! سۆڭەك ۋە مۇسكۇللار بىزگە ھەرىكەتلىنىشكە ياردەم بېرىدۇ، شەخسىي گىگىيەنا بولسا دەنسائاتلىقنى ساقلايدۇ. گەپنى ئوقۇڭ ۋە توغرا ياكى خاتا ئىكەنلىكىنى ھەل قىلىڭ. تەييارمۇسىز؟",
