    bodyhealth_s5_title: "شەخسىي گىگىيەنا",
    bodyhealth_s5_text: "تاماقتىن بۇرۇن قول يۇيۇش مىكروبلاردىن قوغدايدۇ، كۈنىگە ئىككى قېتىم چىش يۇيۇش بولسا چىشلارنى چىرىكتىن ساقلايدۇ. شەخسىي گىگىيەنا دەنسائاتلىقنى ساقلاشنىڭ ئاددىي ئۇسۇلى.",
    bodyhealth_s6_title: "سىز ئۆز تېنىڭىزگە قامخورلۇق قىلىسىز!",
    bodyhealth_s6_text: "بارىس سىزدىن پەخىرلىنىدۇ — ئەمدى سىز تېنىڭىزنىڭ قانداق ئىشلەيدىغانلىقىنى ۋە ئۇنى قانداق پەرۋىش قىلىشنى بىلىسىز! ئويۇندا ئۆزىڭىزنى سىناپ بېقىشقا تەييارمۇسىز؟",
    ball_s1_title: "توپ — شادلىق دوستى!",
    ball_s1_text: "بۈگۈن بارىس توپ بىلەن ئويۇنلارنى كۆرسىتىدۇ! توپ epچىللىق، سۈرئەت ۋە توغرىلىقنى راۋاجلاندۇرىدۇ. سىزگە قانداقتۇر بىر توپ كېرەك — چوڭ ياكى كىچىك، ئەڭ مۇھىمى قولىڭىزغا قولايلىق بولسۇن. ئويناشقا تەييارمۇسىز؟",
